export default Object.freeze({"en":{"name":"Body Water Calculator","title":"Body Water Calculator | UsefulVerse","description":"Estimate adult total body water with the published Watson equations. Free, local and no usage limit; not a hydration test.","intro":"Estimate total body water from adult age, height and weight using a published anthropometric equation. See the estimate in litres and as a share of entered body mass.","howQuestion":"How is total body water estimated?","howAnswer":"Choose one of the Watson equation variants, enter adult age, height and weight, then calculate. The result is a population-based estimate, not a direct measurement.","privacyQuestion":"Are my measurements uploaded?","privacyAnswer":"No. The calculation runs locally in this browser and the values are not uploaded or saved by this tool.","fields":{"equation":"Watson equation variant","watsonMale":"Male equation","watsonFemale":"Female equation","age":"Age (years; adults 18–100)","height":"Height","heightUnit":"Height unit","weight":"Weight","weightUnit":"Weight unit","centimeters":"Centimeters (cm)","inches":"Inches (in)","kilograms":"Kilograms (kg)","pounds":"Pounds (lb)","accuracyNote":"Estimate only; it does not measure hydration or tell you how much to drink. Watson’s 1980 adult equations use male/female categories from their source data and may not fit every person or population. Not for minors, pregnancy, dialysis, edema, diagnosis or clinical decisions. For health questions, ask a qualified clinician.","resultLiters":"Estimated total body water","resultPercent":"Approximate share of body mass","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"Calculate estimate","example":"Try an example","reset":"Clear","result":"Estimate"},"messages":{"calculated":"Estimate calculated.","checkInputs":"Check the adult age, height, weight and selected units."},"additionalFaqs":[{"question":"Is this a hydration or dehydration test?","answer":"No. It estimates total body water from a population equation. It cannot measure hydration status or diagnose dehydration."},{"question":"What does the percentage mean?","answer":"It is estimated litres divided by the entered body mass, treating 1 litre of water as about 1 kilogram. It is not a target or a healthy-range score."},{"question":"Who should not use this estimate for decisions?","answer":"It is not intended for children, pregnancy, dialysis, edema or clinical decisions. A clinician can assess individual health context and direct measurements."}],"copyLanguage":"en","localizationStatus":"approved"},"es":{"name":"Calculadora de agua corporal","title":"Calculadora de agua corporal | UsefulVerse","description":"Estima el agua corporal total de un adulto con las ecuaciones de Watson publicadas.\nGratis, local y sin límite de uso;\nNo es una prueba de hidratación.","intro":"Estimar el agua corporal total a partir de la edad, la altura y el peso de la edad adulta utilizando una ecuación antropométrica publicada.\nVea la estimación en litros y como porcentaje de la masa corporal ingresada.","howQuestion":"¿Cómo se estima el agua corporal total?","howAnswer":"Elija una de las variantes de la ecuación de Watson, ingrese la edad, la altura y el peso de la edad adulta y luego calcule.\nEl resultado es una estimación basada en la población, no una medición directa.","privacyQuestion":"¿Están subidas mis medidas?","privacyAnswer":"No. El cálculo se ejecuta localmente en este navegador y esta herramienta no carga ni guarda los valores.","fields":{"equation":"Variante de la ecuación de Watson","watsonMale":"Ecuación masculina","watsonFemale":"Ecuación femenina","age":"Edad (años; adultos entre 18 y 100 años)","height":"Altura","heightUnit":"Unidad de altura","weight":"Peso","weightUnit":"Unidad de peso","centimeters":"Centímetros (cm)","inches":"Pulgadas (pulg)","kilograms":"Kilogramos (kg)","pounds":"Libras (lb)","accuracyNote":"Sólo estimación;\nno mide la hidratación ni te dice cuánto beber.\nLas ecuaciones de adultos de Watson de 1980 utilizan categorías masculinas/femeninas a partir de sus datos originales y es posible que no se ajusten a todas las personas o poblaciones.\nNo apto para menores de edad, embarazo, diálisis, edemas, diagnóstico o decisiones clínicas.\nSi tiene preguntas sobre salud, consulte a un médico calificado.","resultLiters":"Agua corporal total estimada","resultPercent":"Proporción aproximada de masa corporal","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"Calcular estimación","example":"Pruebe un ejemplo","reset":"Borrar","result":"Estimación"},"messages":{"calculated":"Estimación calculada.","checkInputs":"Consulta edad adulta, altura, peso y unidades seleccionadas."},"additionalFaqs":[{"question":"¿Es esta una prueba de hidratación o deshidratación?","answer":"No. Estima el agua corporal total a partir de una ecuación poblacional.\nNo puede medir el estado de hidratación ni diagnosticar la deshidratación."},{"question":"¿Qué significa el porcentaje?","answer":"Se estiman litros divididos por la masa corporal ingresada, tratando 1 litro de agua como aproximadamente 1 kilogramo.\nNo es un objetivo ni una puntuación de rango saludable."},{"question":"¿Quién no debería utilizar esta estimación para tomar decisiones?","answer":"No está destinado a niños, embarazo, diálisis, edemas ni decisiones clínicas.\nUn médico puede evaluar el contexto de salud individual y las mediciones directas."}],"copyLanguage":"es","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"fr":{"name":"Calculateur d'eau corporelle","title":"Calculateur d'eau corporelle | UsefulVerse","description":"Estimez l’eau corporelle totale d’un adulte à l’aide des équations de Watson publiées.\nGratuit, local et sans limite d'utilisation ;\npas un test…","intro":"Estimez la masse hydrique totale en fonction de l'âge, de la taille et du poids des adultes à l'aide d'une équation anthropométrique publiée.\nVoir l'estimation en litres et en part de la masse corporelle saisie.","howQuestion":"Comment la masse hydrique totale est-elle estimée ?","howAnswer":"Choisissez l'une des variantes de l'équation de Watson, entrez l'âge, la taille et le poids de l'adulte, puis calculez.\nLe résultat est une estimation basée sur la population et non une mesure directe.","privacyQuestion":"Mes mesures sont-elles téléchargées ?","privacyAnswer":"Non. Le calcul s'exécute localement dans ce navigateur et les valeurs ne sont ni téléchargées ni enregistrées par cet outil.","fields":{"equation":"Variante de l'équation de Watson","watsonMale":"Équation masculine","watsonFemale":"Équation féminine","age":"Âge (ans ; adultes de 18 à 100 ans)","height":"Hauteur","heightUnit":"Unité de hauteur","weight":"Poids","weightUnit":"Unité de poids","centimeters":"Centimètres (cm)","inches":"pouces (po)","kilograms":"Kilogrammes (kg)","pounds":"Livres (lb)","accuracyNote":"Estimation seulement ;\nil ne mesure pas l’hydratation et ne vous indique pas la quantité à boire.\nLes équations de Watson pour adultes de 1980 utilisent les catégories hommes/femmes de leurs données sources et peuvent ne pas convenir à chaque personne ou population.\nPas pour les mineurs, grossesse, dialyse, œdème, diagnostic ou décisions cliniques.\nPour des questions de santé, adressez-vous à un clinicien qualifié.","resultLiters":"Eau corporelle totale estimée","resultPercent":"Part approximative de la masse corporelle","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"Calculer l'estimation","example":"Essayez un exemple","reset":"Effacer","result":"Estimation"},"messages":{"calculated":"Estimation calculée.","checkInputs":"Vérifiez l'âge adulte, la taille, le poids et les unités sélectionnées."},"additionalFaqs":[{"question":"Est-ce un test d'hydratation ou de déshydratation ?","answer":"Non. Il estime la masse hydrique totale à partir d’une équation de population.\nIl ne peut pas mesurer l’état d’hydratation ni diagnostiquer la déshydratation."},{"question":"Que signifie le pourcentage ?","answer":"On estime les litres divisés par la masse corporelle saisie, en traitant 1 litre d'eau comme environ 1 kilogramme.\nIl ne s’agit pas d’un objectif ou d’un score sain."},{"question":"Qui ne devrait pas utiliser cette estimation pour prendre des décisions ?","answer":"Il n'est pas destiné aux enfants, à la grossesse, à la dialyse, à l'œdème ou aux décisions cliniques.\nUn clinicien peut évaluer le contexte de santé individuel et diriger les mesures."}],"copyLanguage":"fr","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"pt":{"name":"Calculadora de Água Corporal","title":"Calculadora de Água Corporal | UsefulVerse","description":"Estime a água corporal total de adultos com as equações de Watson publicadas.\nGratuito, local e sem limite de uso;\nnão é um teste de hidratação.","intro":"Estime a água corporal total a partir da idade, altura e peso do adulto usando uma equação antropométrica publicada.\nVeja a estimativa em litros e como proporção da massa corporal inserida.","howQuestion":"Como é estimada a água corporal total?","howAnswer":"Escolha uma das variantes da equação de Watson, insira a idade adulta, altura e peso e depois calcule.\nO resultado é uma estimativa baseada na população e não uma medição direta.","privacyQuestion":"Minhas medições foram carregadas?","privacyAnswer":"Não. O cálculo é executado localmente neste navegador e os valores não são carregados ou salvos por esta ferramenta.","fields":{"equation":"Variante da equação de Watson","watsonMale":"Equação masculina","watsonFemale":"Equação feminina","age":"Idade (anos; adultos de 18 a 100)","height":"Altura","heightUnit":"Unidade de altura","weight":"Peso","weightUnit":"Unidade de peso","centimeters":"Centímetros (cm)","inches":"Polegadas (pol.)","kilograms":"Quilogramas (kg)","pounds":"Libras (lb)","accuracyNote":"Somente estimativa;\nnão mede a hidratação nem informa quanto beber.\nAs equações para adultos de Watson de 1980 utilizam categorias masculino/feminino a partir dos seus dados de origem e podem não se ajustar a todas as pessoas ou populações.\nNão para menores, gravidez, diálise, edema, diagnóstico ou decisões clínicas.\nPara questões de saúde, pergunte a um médico qualificado.","resultLiters":"Água corporal total estimada","resultPercent":"Participação aproximada da massa corporal","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"Calcular estimativa","example":"Experimente um exemplo","reset":"Claro","result":"Estimativa"},"messages":{"calculated":"Estimativa calculada.","checkInputs":"Verifique a idade do adulto, altura, peso e unidades selecionadas."},"additionalFaqs":[{"question":"Este é um teste de hidratação ou desidratação?","answer":"Não. Estima a água corporal total a partir de uma equação populacional.\nNão pode medir o estado de hidratação ou diagnosticar desidratação."},{"question":"O que significa a porcentagem?","answer":"Estima-se litros divididos pela massa corporal inserida, tratando 1 litro de água como cerca de 1 quilograma.\nNão é uma meta ou uma pontuação saudável."},{"question":"Quem não deve usar esta estimativa para decisões?","answer":"Não se destina a crianças, gravidez, diálise, edema ou decisões clínicas.\nUm médico pode avaliar o contexto de saúde individual e medições diretas."}],"copyLanguage":"pt","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"de":{"name":"Körperwasserrechner","title":"Körperwasserrechner | UsefulVerse","description":"Schätzen Sie das Gesamtkörperwasser eines Erwachsenen mit den veröffentlichten Watson-Gleichungen.\nKostenlos, lokal und ohne Nutzungsbeschränkung;\nkein…","intro":"Schätzen Sie das Gesamtkörperwasser anhand von Alter, Größe und Gewicht des Erwachsenen mithilfe einer veröffentlichten anthropometrischen Gleichung.\nSehen Sie sich die Schätzung in Litern und als Anteil der eingegebenen Körpermasse an.","howQuestion":"Wie wird das Gesamtkörperwasser geschätzt?","howAnswer":"Wählen Sie eine der Watson-Gleichungsvarianten, geben Sie das Erwachsenenalter, die Größe und das Gewicht ein und berechnen Sie dann.\nDas Ergebnis ist eine bevölkerungsbasierte Schätzung, keine direkte Messung.","privacyQuestion":"Werden meine Maße hochgeladen?","privacyAnswer":"Nein. Die Berechnung läuft lokal in diesem Browser und die Werte werden von diesem Tool nicht hochgeladen oder gespeichert.","fields":{"equation":"Variante der Watson-Gleichung","watsonMale":"Männliche Gleichung","watsonFemale":"Weibliche Gleichung","age":"Alter (Jahre; Erwachsene 18–100)","height":"Höhe","heightUnit":"Höheneinheit","weight":"Gewicht","weightUnit":"Gewichtseinheit","centimeters":"Zentimeter (cm)","inches":"Zoll (Zoll)","kilograms":"Kilogramm (kg)","pounds":"Pfund (lb)","accuracyNote":"Nur Schätzung;\nEs misst nicht die Flüssigkeitszufuhr und sagt Ihnen nicht, wie viel Sie trinken sollten.\nWatsons Gleichungen für Erwachsene aus dem Jahr 1980 verwenden die Kategorien männlich/weiblich aus ihren Quelldaten und passen möglicherweise nicht für jede Person oder Bevölkerung.\nNicht für Minderjährige, Schwangerschaft, Dialyse, Ödeme, Diagnose oder klinische Entscheidungen.\nBei gesundheitlichen Fragen wenden Sie sich an einen qualifizierten Arzt.","resultLiters":"Geschätzte Gesamtkörperwassermenge","resultPercent":"Ungefährer Anteil an der Körpermasse","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"Kostenvoranschlag berechnen","example":"Versuchen Sie es mit einem Beispiel","reset":"Klar","result":"Kostenvoranschlag"},"messages":{"calculated":"Kostenvoranschlag berechnet.","checkInputs":"Überprüfen Sie das Alter, die Größe, das Gewicht und die ausgewählten Einheiten des Erwachsenen."},"additionalFaqs":[{"question":"Handelt es sich um einen Hydratations- oder Dehydrationstest?","answer":"Nein. Es schätzt das Gesamtkörperwasser anhand einer Bevölkerungsgleichung.\nEs kann weder den Flüssigkeitsstatus messen noch eine Dehydrierung diagnostizieren."},{"question":"Was bedeutet der Prozentsatz?","answer":"Es handelt sich um geschätzte Liter dividiert durch die eingegebene Körpermasse, wobei 1 Liter Wasser etwa 1 Kilogramm entspricht.\nEs handelt sich nicht um einen Zielwert oder einen Wert im gesunden Bereich."},{"question":"Wer sollte diese Schätzung nicht für Entscheidungen nutzen?","answer":"Es ist nicht für Kinder, Schwangerschaft, Dialyse, Ödeme oder klinische Entscheidungen bestimmt.\nEin Arzt kann den individuellen Gesundheitskontext beurteilen und direkte Messungen durchführen."}],"copyLanguage":"de","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"ja":{"name":"体内水分計算機","title":"体内水分計算機 | UsefulVerse","description":"公開されているワトソン方程式を使用して成人の総体内水を推定します。\n無料、ローカル、使用制限なし。\n水分補給テストではありません。","intro":"公開されている人体計測方程式を使用して、成人の年齢、身長、体重から体内の総水を推定します。\n入力した体重に対する推定値をリットル単位で表示します。","howQuestion":"体内総水分量はどのように推定されますか?","howAnswer":"ワトソン方程式のバリエーションの 1 つを選択し、成人の年齢、身長、体重を入力して計算します。\n結果は、直接測定されたものではなく、母集団に基づいた推定値です。","privacyQuestion":"私の測定値はアップロードされていますか?","privacyAnswer":"いいえ。計算はこのブラウザーでローカルに実行され、値はこのツールによってアップロードまたは保存されません。","fields":{"equation":"ワトソン方程式の変形","watsonMale":"男性の方程式","watsonFemale":"女性の方程式","age":"年齢 (歳、成人 18 ～ 100 歳)","height":"身長","heightUnit":"高さ単位","weight":"重量","weightUnit":"重量単位","centimeters":"センチメートル (cm)","inches":"インチ (インチ)","kilograms":"キログラム (kg)","pounds":"ポンド (lb)","accuracyNote":"見積もりのみ。\n水分補給を測定したり、飲む量を教えたりするものではありません。\nワトソンの 1980 年の成人の方程式は、ソース データから男性/女性のカテゴリーを使用しているため、すべての人や集団に適合するとは限りません。\n未成年者、妊娠、透析、浮腫、診断または臨床上の決定には適していません。\n健康に関する質問については、資格のある臨床医にお尋ねください。","resultLiters":"推定体内総水分量","resultPercent":"体重に占めるおおよその割合","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"見積もりを計算する","example":"例を試してください","reset":"クリア","result":"見積もり"},"messages":{"calculated":"見積もりが計算されました。","checkInputs":"成人の年齢、身長、体重、選択した単位を確認してください。"},"additionalFaqs":[{"question":"これは水分補給テストですか、それとも脱水テストですか?","answer":"いいえ。人口方程式から体内の総水分を推定します。\n水分補給状態を測定したり、脱水症状を診断したりすることはできません。"},{"question":"パーセンテージとは何を意味しますか?","answer":"水 1 リットルを約 1 キログラムとして扱い、入力された体重でリットルを割った推定値です。\nこれは目標値や健全な範囲のスコアではありません。"},{"question":"この推定値を意思決定に使用すべきでないのは誰ですか?","answer":"小児、妊娠、透析、浮腫、または臨床上の判断を対象としたものではありません。\n臨床医は、個人の健康状況を評価し、測定を直接行うことができます。"}],"copyLanguage":"ja","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"ko":{"name":"체수분 계산기","title":"체수분 계산기 | UsefulVerse","description":"공개된 Watson 방정식을 사용하여 성인의 총 체수분을 추정합니다.\n무료이며 로컬이며 사용 제한이 없습니다.\n수분 테스트가 아닙니다.","intro":"발표된 인체 측정 방정식을 사용하여 성인 연령, 키, 체중으로부터 총 체수분을 추정합니다.\n리터 단위와 입력된 체질량의 비율로 추정치를 확인하세요.","howQuestion":"총 체수분은 어떻게 추정되나요?","howAnswer":"Watson 방정식 변형 중 하나를 선택하고 성인 연령, 키, 체중을 입력한 후 계산합니다.\n결과는 직접적인 측정이 아닌 모집단 기반 추정치입니다.","privacyQuestion":"내 측정값이 업로드되나요?","privacyAnswer":"아니요. 계산은 이 브라우저에서 로컬로 실행되며 이 도구는 값을 업로드하거나 저장하지 않습니다.","fields":{"equation":"Watson 방정식 변형","watsonMale":"남성 방정식","watsonFemale":"여성 방정식","age":"연령(세; 성인 18~100)","height":"키","heightUnit":"높이 단위","weight":"무게","weightUnit":"중량 단위","centimeters":"센티미터 (cm)","inches":"인치(인치)","kilograms":"킬로그램 (kg)","pounds":"파운드(파운드)","accuracyNote":"추정만;\n수분 섭취량을 측정하거나 마시는 양을 알려주지 않습니다.\nWatson의 1980년 성인 방정식은 소스 데이터의 남성/여성 범주를 사용하므로 모든 사람이나 모집단에 적합하지 않을 수 있습니다.\n미성년자, 임신, 투석, 부종, 진단 또는 임상 결정에는 적용되지 않습니다.\n건강 관련 질문은 자격을 갖춘 임상의에게 문의하세요.","resultLiters":"추정 총 체수분","resultPercent":"체질량의 대략적인 비율","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"추정 계산","example":"예시를 들어보세요","reset":"지우기","result":"추정"},"messages":{"calculated":"추정치가 계산되었습니다.","checkInputs":"성인 연령, 키, 체중 및 선택한 단위를 확인하세요."},"additionalFaqs":[{"question":"이것은 수분 공급 테스트입니까, 탈수 테스트입니까?","answer":"아니요. 인구 방정식을 통해 총 체수분을 추정합니다.\n수분 상태를 측정하거나 탈수를 진단할 수는 없습니다."},{"question":"백분율은 무엇을 의미하나요?","answer":"리터를 입력된 체질량으로 나눈 추정치로, 물 1리터를 약 1킬로그램으로 취급합니다.\n이는 목표 또는 건강한 범위 점수가 아닙니다."},{"question":"누가 이 추정치를 결정에 사용해서는 안 됩니까?","answer":"어린이, 임신, 투석, 부종 또는 임상 결정을 위한 것이 아닙니다.\n임상의는 개인의 건강 상황을 평가하고 직접 측정할 수 있습니다."}],"copyLanguage":"ko","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"id":{"name":"Kalkulator Air Tubuh","title":"Kalkulator Air Tubuh | UsefulVerse","description":"Perkirakan total air tubuh orang dewasa dengan persamaan Watson yang dipublikasikan.\nGratis, lokal dan tanpa batas penggunaan;\nbukan tes hidrasi.","intro":"Perkirakan total air tubuh dari usia dewasa, tinggi dan berat badan menggunakan persamaan antropometri yang dipublikasikan.\nLihat perkiraan dalam liter dan sebagai bagian dari massa tubuh yang dimasukkan.","howQuestion":"Bagaimana perkiraan total air tubuh?","howAnswer":"Pilih salah satu varian persamaan Watson, masukkan usia dewasa, tinggi badan dan berat badan, lalu hitung.\nHasilnya adalah perkiraan berdasarkan populasi, bukan pengukuran langsung.","privacyQuestion":"Apakah pengukuran saya sudah diunggah?","privacyAnswer":"Tidak. Perhitungan berjalan secara lokal di browser ini dan nilainya tidak diunggah atau disimpan oleh alat ini.","fields":{"equation":"Varian persamaan Watson","watsonMale":"Persamaan laki-laki","watsonFemale":"Persamaan wanita","age":"Usia (tahun; dewasa 18–100)","height":"Tinggi","heightUnit":"Satuan tinggi","weight":"Berat","weightUnit":"Satuan berat","centimeters":"Sentimeter (cm)","inches":"Inci (dalam)","kilograms":"Kilogram (kg)","pounds":"Pound (pon)","accuracyNote":"Hanya perkiraan;\nitu tidak mengukur hidrasi atau memberi tahu Anda berapa banyak yang harus diminum.\nPersamaan orang dewasa Watson tahun 1980 menggunakan kategori laki-laki/perempuan dari sumber datanya dan mungkin tidak cocok untuk setiap orang atau populasi.\nTidak untuk anak di bawah umur, kehamilan, cuci darah, edema, diagnosis atau keputusan klinis.\nUntuk pertanyaan kesehatan, tanyakan pada dokter yang berkualifikasi.","resultLiters":"Perkiraan total air tubuh","resultPercent":"Perkiraan bagian massa tubuh","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"Hitung perkiraan","example":"Coba contoh","reset":"Jelas","result":"Perkiraan"},"messages":{"calculated":"Perkiraan dihitung.","checkInputs":"Periksa usia dewasa, tinggi badan, berat badan dan unit yang dipilih."},"additionalFaqs":[{"question":"Ini tes hidrasi atau dehidrasi?","answer":"Tidak. Ini memperkirakan total air tubuh dari persamaan populasi.\nItu tidak dapat mengukur status hidrasi atau mendiagnosis dehidrasi."},{"question":"Apa yang dimaksud dengan persentase?","answer":"Diperkirakan liter dibagi dengan massa tubuh yang dimasukkan, sehingga 1 liter air sama dengan 1 kilogram.\nIni bukan target atau rentang skor yang sehat."},{"question":"Siapa yang tidak boleh menggunakan perkiraan ini untuk mengambil keputusan?","answer":"Tidak ditujukan untuk anak-anak, kehamilan, dialisis, edema, atau pengambilan keputusan klinis.\nSeorang dokter dapat menilai konteks kesehatan individu dan pengukuran langsung."}],"copyLanguage":"id","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"hi":{"name":"शारीरिक जल कैलकुलेटर","title":"शारीरिक जल कैलकुलेटर | UsefulVerse","description":"प्रकाशित वाटसन समीकरणों के साथ वयस्क के शरीर में कुल पानी का अनुमान लगाएं।\nमुफ़्त, स्थानीय और कोई उपयोग सीमा नहीं;\nजलयोजन परीक्षण नहीं.","intro":"एक प्रकाशित एंथ्रोपोमेट्रिक समीकरण का उपयोग करके वयस्क आयु, ऊंचाई और वजन से शरीर के कुल पानी का अनुमान लगाएं।\nअनुमान लीटर में और प्रविष्ट शरीर द्रव्यमान के हिस्से के रूप में देखें।","howQuestion":"शरीर के कुल पानी का अनुमान कैसे लगाया जाता है?","howAnswer":"वॉटसन समीकरण वेरिएंट में से एक चुनें, वयस्क आयु, ऊंचाई और वजन दर्ज करें, फिर गणना करें।\nपरिणाम जनसंख्या-आधारित अनुमान है, प्रत्यक्ष माप नहीं।","privacyQuestion":"क्या मेरे माप अपलोड किए गए हैं?","privacyAnswer":"नहीं। गणना इस ब्राउज़र में स्थानीय रूप से चलती है और इस टूल द्वारा मान अपलोड या सहेजे नहीं जाते हैं।","fields":{"equation":"वाटसन समीकरण प्रकार","watsonMale":"पुरुष समीकरण","watsonFemale":"महिला समीकरण","age":"आयु (वर्ष; वयस्क 18-100)","height":"ऊंचाई","heightUnit":"ऊंचाई इकाई","weight":"वजन","weightUnit":"भार इकाई","centimeters":"सेंटीमीटर (सेमी)","inches":"इंच (इंच)","kilograms":"किलोग्राम (किग्रा)","pounds":"पाउंड (पौंड)","accuracyNote":"केवल अनुमान;\nयह जलयोजन को मापता नहीं है या आपको बताता है कि कितना पीना है।\nवॉटसन के 1980 के वयस्क समीकरण उनके स्रोत डेटा से पुरुष/महिला श्रेणियों का उपयोग करते हैं और प्रत्येक व्यक्ति या जनसंख्या में फिट नहीं हो सकते हैं।\nनाबालिगों, गर्भावस्था, डायलिसिस, एडिमा, निदान या नैदानिक ​​निर्णयों के लिए नहीं।\nस्वास्थ्य संबंधी प्रश्नों के लिए किसी योग्य चिकित्सक से पूछें।","resultLiters":"शरीर में कुल पानी का अनुमान","resultPercent":"शरीर द्रव्यमान का अनुमानित हिस्सा","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"अनुमान की गणना करें","example":"एक उदाहरण आज़माएँ","reset":"साफ़","result":"अनुमान"},"messages":{"calculated":"अनुमान की गणना।","checkInputs":"वयस्क आयु, ऊंचाई, वजन और चयनित इकाइयों की जांच करें।"},"additionalFaqs":[{"question":"क्या यह जलयोजन या निर्जलीकरण परीक्षण है?","answer":"नहीं। यह जनसंख्या समीकरण से शरीर के कुल पानी का अनुमान लगाता है।\nयह जलयोजन की स्थिति को माप नहीं सकता या निर्जलीकरण का निदान नहीं कर सकता।"},{"question":"प्रतिशत का क्या मतलब है?","answer":"यह अनुमान है कि लीटर को शरीर के दर्ज द्रव्यमान से विभाजित किया जाता है, 1 लीटर पानी को लगभग 1 किलोग्राम माना जाता है।\nयह कोई लक्ष्य या स्वस्थ-श्रेणी स्कोर नहीं है।"},{"question":"किसे निर्णयों के लिए इस अनुमान का उपयोग नहीं करना चाहिए?","answer":"यह बच्चों, गर्भावस्था, डायलिसिस, एडिमा या नैदानिक ​​निर्णयों के लिए नहीं है।\nएक चिकित्सक व्यक्तिगत स्वास्थ्य संदर्भ और प्रत्यक्ष माप का आकलन कर सकता है।"}],"copyLanguage":"hi","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"ar":{"name":"حاسبة مياه الجسم","title":"حاسبة مياه الجسم | UsefulVerse","description":"تقدير إجمالي مياه الجسم للبالغين باستخدام معادلات واتسون المنشورة.\nمجاني ومحلي وبدون حدود للاستخدام؛\nليس اختبار الترطيب.","intro":"قم بتقدير إجمالي مياه الجسم من عمر البالغين والطول والوزن باستخدام معادلة القياسات البشرية المنشورة.\nانظر التقدير باللتر وكنسبة من كتلة الجسم المدخلة.","howQuestion":"كيف يتم تقدير إجمالي مياه الجسم؟","howAnswer":"اختر أحد متغيرات معادلة Watson، وأدخل عمر الشخص البالغ وطوله ووزنه، ثم قم بالحساب.\nوالنتيجة هي تقدير على أساس السكان، وليس قياسا مباشرا.","privacyQuestion":"هل تم تحميل قياساتي؟","privacyAnswer":"لا. يتم تشغيل الحساب محليًا في هذا المتصفح ولا يتم تحميل القيم أو حفظها بواسطة هذه الأداة.","fields":{"equation":"متغير معادلة واتسون","watsonMale":"معادلة ذكر","watsonFemale":"معادلة أنثى","age":"العمر (بالسنوات، البالغون 18-100)","height":"الارتفاع","heightUnit":"وحدة الارتفاع","weight":"الوزن","weightUnit":"وحدة الوزن","centimeters":"سم (سم)","inches":"بوصة (بوصة)","kilograms":"كيلوغرام (كجم)","pounds":"جنيه (رطل)","accuracyNote":"تقدير فقط؛\nفهو لا يقيس نسبة الماء في الجسم ولا يخبرك بالكمية التي تشربها.\nتستخدم معادلات واتسون للبالغين لعام 1980 فئات الذكور/الإناث من بيانات مصدرها وقد لا تناسب كل شخص أو مجموعة سكانية.\nليس للقاصرين، الحمل، غسيل الكلى، الوذمة، التشخيص أو القرارات السريرية.\nللأسئلة الصحية، اسأل طبيب مؤهل.","resultLiters":"إجمالي مياه الجسم المقدرة","resultPercent":"الحصة التقريبية من كتلة الجسم","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"حساب التقدير","example":"جرب مثالا","reset":"واضح","result":"تقدير"},"messages":{"calculated":"تم حساب التقدير.","checkInputs":"تحقق من عمر البالغ وطوله ووزنه والوحدات المختارة."},"additionalFaqs":[{"question":"هل هذا اختبار ترطيب أم جفاف؟","answer":"رقم. فهو يقدر إجمالي مياه الجسم من المعادلة السكانية.\nولا يمكنه قياس حالة الترطيب أو تشخيص الجفاف."},{"question":"ماذا تعني النسبة؟","answer":"ويقدر اللترات مقسومة على كتلة الجسم المدخلة، ويعامل 1 لتر من الماء بحوالي 1 كيلوجرام.\nإنه ليس هدفًا أو نتيجة نطاق صحي."},{"question":"من الذي لا يجب عليه استخدام هذا التقدير لاتخاذ القرارات؟","answer":"ليس مخصصًا للأطفال أو الحمل أو غسيل الكلى أو الوذمة أو القرارات السريرية.\nيمكن للطبيب تقييم السياق الصحي الفردي والقياسات المباشرة.\nتمت الموافقة على"}],"copyLanguage":"ar","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"zh":{"name":"身体水分计算器","title":"身体水分计算器 | UsefulVerse","description":"使用已发布的 Watson 方程估算成人体内总水分。\n免费、本地且无使用限制；\n不是水合测试。","intro":"使用已发布的人体测量方程根据成人年龄、身高和体重估算体内水分总量。\n查看以升为单位的估计值以及输入的体重的百分比。","howQuestion":"体内总水分是如何估算的？","howAnswer":"选择 Watson 方程变体之一，输入成人年龄、身高和体重，然后进行计算。\n结果是基于人口的估计，而不是直接测量。","privacyQuestion":"我的测量结果上传了吗？","privacyAnswer":"否。计算在此浏览器中本地运行，并且该工具不会上传或保存值。","fields":{"equation":"Watson 方程变体","watsonMale":"男方程","watsonFemale":"女方程","age":"年龄（岁；成人 18–100）","height":"身高","heightUnit":"高度单位","weight":"重量","weightUnit":"重量单位","centimeters":"厘米 (cm)","inches":"英寸 (in)","kilograms":"公斤 (kg)","pounds":"磅 (lb)","accuracyNote":"仅估算；\n它不会测量水合作用或告诉您喝多少水。\nWatson 的 1980 年成人方程使用源数据中的男性/女性类别，可能并不适合每个人或人群。\n不适用于未成年人、怀孕、透析、水肿、诊断或临床决策。\n对于健康问题，请咨询合格的临床医生。","resultLiters":"估计体内总水分","resultPercent":"体重的大约比例","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"计算估算","example":"尝试一个例子","reset":"清除","result":"预估"},"messages":{"calculated":"计算得出的估计值。","checkInputs":"检查成人年龄、身高、体重和所选单位。"},"additionalFaqs":[{"question":"这是水合或脱水测试吗？","answer":"否。它根据人口方程估算体内总水分。\n它无法测量水合状态或诊断脱水。"},{"question":"百分比是什么意思？","answer":"估计升数除以输入的体重，将 1 升水视为约 1 公斤。\n它不是目标或健康范围分数。"},{"question":"谁不应该使用此估计进行决策？","answer":"不适用于儿童、怀孕、透析、水肿或临床决策。\n临床医生可以评估个人健康状况并进行直接测量。"}],"copyLanguage":"zh","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"bn":{"name":"বডি ওয়াটার ক্যালকুলেটর","title":"বডি ওয়াটার ক্যালকুলেটর | UsefulVerse","description":"প্রকাশিত ওয়াটসন সমীকরণ সহ প্রাপ্তবয়স্কদের শরীরের মোট জল অনুমান করুন।\nবিনামূল্যে, স্থানীয় এবং ব্যবহারের সীমা নেই;\nহাইড্রেশন পরীক্ষা নয়।","intro":"একটি প্রকাশিত নৃতাত্ত্বিক সমীকরণ ব্যবহার করে প্রাপ্তবয়স্ক বয়স, উচ্চতা এবং ওজন থেকে শরীরের মোট জল অনুমান করুন।\nঅনুমানটি লিটারে এবং প্রবেশ করা শরীরের ভরের ভাগ হিসাবে দেখুন।","howQuestion":"শরীরের মোট জল কিভাবে অনুমান করা হয়?","howAnswer":"ওয়াটসন সমীকরণ ভেরিয়েন্টের একটি বেছে নিন, প্রাপ্তবয়স্কদের বয়স, উচ্চতা এবং ওজন লিখুন, তারপর গণনা করুন।\nফলাফল একটি জনসংখ্যা-ভিত্তিক অনুমান, সরাসরি পরিমাপ নয়।","privacyQuestion":"আমার পরিমাপ কি আপলোড করা হয়েছে?","privacyAnswer":"নং। গণনা এই ব্রাউজারে স্থানীয়ভাবে চলে এবং মানগুলি এই টুল দ্বারা আপলোড বা সংরক্ষণ করা হয় না।","fields":{"equation":"ওয়াটসন সমীকরণ বৈকল্পিক","watsonMale":"পুরুষ সমীকরণ","watsonFemale":"মহিলা সমীকরণ","age":"বয়স (বছর; প্রাপ্তবয়স্ক 18-100)","height":"উচ্চতা","heightUnit":"উচ্চতা ইউনিট","weight":"ওজন","weightUnit":"ওজন ইউনিট","centimeters":"সেন্টিমিটার (সেমি)","inches":"ইঞ্চি (ইন)","kilograms":"কিলোগ্রাম (কেজি)","pounds":"পাউন্ড (পাউন্ড)","accuracyNote":"শুধুমাত্র অনুমান;\nএটি হাইড্রেশন পরিমাপ করে না বা আপনাকে কতটা পান করতে হবে তা বলে না।\nওয়াটসনের 1980 প্রাপ্তবয়স্ক সমীকরণগুলি তাদের উত্স ডেটা থেকে পুরুষ/মহিলা বিভাগগুলি ব্যবহার করে এবং প্রতিটি ব্যক্তি বা জনসংখ্যার জন্য উপযুক্ত নাও হতে পারে।\nঅপ্রাপ্তবয়স্কদের জন্য নয়, গর্ভাবস্থা, ডায়ালাইসিস, শোথ, রোগ নির্ণয় বা ক্লিনিকাল সিদ্ধান্ত।\nস্বাস্থ্য সংক্রান্ত প্রশ্নের জন্য, একজন যোগ্য চিকিত্সককে জিজ্ঞাসা করুন।","resultLiters":"আনুমানিক মোট শরীরের জল","resultPercent":"শরীরের ভরের আনুমানিক ভাগ","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"অনুমান গণনা করুন","example":"একটি উদাহরণ চেষ্টা করুন","reset":"সাফ","result":"অনুমান"},"messages":{"calculated":"হিসাব করা হয়েছে।","checkInputs":"প্রাপ্তবয়স্কদের বয়স, উচ্চতা, ওজন এবং নির্বাচিত ইউনিট পরীক্ষা করুন।"},"additionalFaqs":[{"question":"এটি কি একটি হাইড্রেশন বা ডিহাইড্রেশন পরীক্ষা?","answer":"নং। এটি জনসংখ্যার সমীকরণ থেকে শরীরের মোট জল অনুমান করে।\nএটি হাইড্রেশন স্থিতি পরিমাপ করতে পারে না বা ডিহাইড্রেশন নির্ণয় করতে পারে না।"},{"question":"শতাংশ মানে কি?","answer":"আনুমানিক লিটারকে প্রবেশ করা শরীরের ভর দ্বারা ভাগ করা হয়, 1 লিটার জলকে প্রায় 1 কিলোগ্রাম হিসাবে বিবেচনা করা হয়।\nএটি একটি লক্ষ্য বা একটি স্বাস্থ্যকর-রেঞ্জ স্কোর নয়।"},{"question":"কার সিদ্ধান্তের জন্য এই অনুমান ব্যবহার করা উচিত নয়?","answer":"এটি শিশু, গর্ভাবস্থা, ডায়ালাইসিস, শোথ বা ক্লিনিকাল সিদ্ধান্তের জন্য নয়।\nএকজন চিকিত্সক স্বতন্ত্র স্বাস্থ্য প্রসঙ্গ এবং সরাসরি পরিমাপ মূল্যায়ন করতে পারেন।"}],"copyLanguage":"bn","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"ru":{"name":"Калькулятор воды в организме","title":"Калькулятор воды в организме | UsefulVerse","description":"Оцените общее количество воды в организме взрослого человека с помощью опубликованных уравнений Уотсона.\nБесплатно, локально и без ограничений по…","intro":"Оцените общее количество воды в организме, исходя из возраста, роста и веса взрослого человека, используя опубликованное антропометрическое уравнение.\nСм. оценку в литрах и в долях от введенной массы тела.","howQuestion":"Как оценивается общее количество воды в организме?","howAnswer":"Выберите один из вариантов уравнения Ватсона, введите возраст, рост и вес взрослого человека, а затем произведите расчет.\nРезультатом является оценка на основе численности населения, а не прямое измерение.","privacyQuestion":"Мои мерки загружены?","privacyAnswer":"Нет. Расчет выполняется локально в этом браузере, и значения не загружаются и не сохраняются с помощью этого инструмента.","fields":{"equation":"Вариант уравнения Ватсона","watsonMale":"Мужское уравнение","watsonFemale":"Женское уравнение","age":"Возраст (лет; взрослые 18–100)","height":"Высота","heightUnit":"Единица высоты","weight":"Вес","weightUnit":"Весовой блок","centimeters":"Сантиметры (см)","inches":"Дюймы (дюймы)","kilograms":"Килограммы (кг)","pounds":"Фунтов (фунтов)","accuracyNote":"Только оценка;\nон не измеряет уровень гидратации и не сообщает вам, сколько пить.\nУравнения для взрослых Уотсона 1980 года используют категории мужчин и женщин из исходных данных и могут не подходить каждому человеку или группе населения.\nНе для несовершеннолетних, беременности, диализа, отеков, диагностики или клинических решений.\nПо вопросам здоровья обращайтесь к квалифицированному врачу.","resultLiters":"Примерное общее количество воды в организме","resultPercent":"Примерная доля массы тела","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"Рассчитать смету","example":"Попробуйте пример.","reset":"Прозрачный","result":"Оценка"},"messages":{"calculated":"Смета рассчитана.","checkInputs":"Проверьте возраст взрослого, рост, вес и выбранные единицы измерения."},"additionalFaqs":[{"question":"Это тест на гидратацию или обезвоживание?","answer":"Нет. Он оценивает общее количество воды в организме на основе уравнения численности населения.\nОн не может измерить состояние гидратации или диагностировать обезвоживание."},{"question":"Что означает процент?","answer":"Это рассчитано в литрах, разделенных на введенную массу тела, при этом 1 литр воды равен примерно 1 килограмму.\nЭто не цель или показатель здорового диапазона."},{"question":"Кому не следует использовать эту оценку для принятия решений?","answer":"Он не предназначен для детей, беременности, диализа, отеков или клинических решений.\nВрач может оценить индивидуальный контекст здоровья и провести прямые измерения."}],"copyLanguage":"ru","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"ur":{"name":"باڈی واٹر کیلکولیٹر","title":"باڈی واٹر کیلکولیٹر | UsefulVerse","description":"شائع شدہ واٹسن مساوات کے ساتھ بالغوں کے جسم کے پانی کا تخمینہ لگائیں۔\nمفت، مقامی اور استعمال کی کوئی حد نہیں؛\nہائیڈریشن ٹیسٹ نہیں","intro":"ایک شائع شدہ اینتھروپومیٹرک مساوات کا استعمال کرتے ہوئے بالغ عمر، قد اور وزن سے جسم کے کل پانی کا اندازہ لگائیں۔\nتخمینہ لیٹر میں اور داخل شدہ باڈی ماس کے حصہ کے طور پر دیکھیں۔","howQuestion":"جسم کے کل پانی کا اندازہ کیسے لگایا جاتا ہے؟","howAnswer":"واٹسن مساوات کی مختلف حالتوں میں سے ایک کا انتخاب کریں، بالغ عمر، قد اور وزن درج کریں، پھر حساب لگائیں۔\nنتیجہ آبادی پر مبنی تخمینہ ہے، براہ راست پیمائش نہیں۔","privacyQuestion":"کیا میری پیمائشیں اپ لوڈ کی گئی ہیں؟","privacyAnswer":"نمبر۔ حساب اس براؤزر میں مقامی طور پر چلتا ہے اور اس ٹول کے ذریعے ویلیوز اپ لوڈ یا محفوظ نہیں کی جاتی ہیں۔","fields":{"equation":"واٹسن ایکویشن ویرینٹ","watsonMale":"مردانہ مساوات","watsonFemale":"خواتین کی مساوات","age":"عمر (سال؛ بالغ 18-100)","height":"اونچائی","heightUnit":"اونچائی یونٹ","weight":"وزن","weightUnit":"ویٹ یونٹ","centimeters":"سینٹی میٹر (سینٹی میٹر)","inches":"انچ (میں)","kilograms":"کلوگرام (کلوگرام)","pounds":"پاؤنڈز (lb)","accuracyNote":"تخمینہ صرف;\nیہ ہائیڈریشن کی پیمائش نہیں کرتا یا آپ کو یہ نہیں بتاتا کہ کتنا پینا ہے۔\nواٹسن کی 1980 بالغ مساواتیں اپنے ماخذ ڈیٹا سے مرد/خواتین کے زمرے استعمال کرتی ہیں اور ہو سکتا ہے کہ ہر فرد یا آبادی کے لیے موزوں نہ ہوں۔\nنابالغوں، حمل، ڈائیلاسز، ورم، تشخیص یا طبی فیصلوں کے لیے نہیں۔\nصحت سے متعلق سوالات کے لیے، کسی مستند طبیب سے پوچھیں۔","resultLiters":"تخمینہ شدہ کل جسمانی پانی","resultPercent":"باڈی ماس کا تخمینی حصہ","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"تخمینہ لگائیں۔","example":"ایک مثال آزمائیں۔","reset":"صاف کریں۔","result":"تخمینہ"},"messages":{"calculated":"تخمینہ لگایا گیا۔","checkInputs":"بالغوں کی عمر، قد، وزن اور منتخب یونٹس چیک کریں۔"},"additionalFaqs":[{"question":"کیا یہ ہائیڈریشن یا ڈی ہائیڈریشن ٹیسٹ ہے؟","answer":"نمبر۔ یہ آبادی کی مساوات سے جسم کے کل پانی کا تخمینہ لگاتا ہے۔\nیہ ہائیڈریشن کی حیثیت کی پیمائش یا ڈی ہائیڈریشن کی تشخیص نہیں کر سکتا۔"},{"question":"فیصد کا کیا مطلب ہے؟","answer":"یہ اندازہ لگایا جاتا ہے کہ لیٹر کو داخل شدہ جسم کے بڑے پیمانے پر تقسیم کیا جاتا ہے، 1 لیٹر پانی کو تقریباً 1 کلو گرام سمجھا جاتا ہے۔\nیہ ایک ہدف یا صحت مند رینج اسکور نہیں ہے۔"},{"question":"اس تخمینہ کو فیصلوں کے لیے کسے استعمال نہیں کرنا چاہیے؟","answer":"یہ بچوں، حمل، ڈائیلاسز، ورم یا طبی فیصلوں کے لیے نہیں ہے۔\nایک معالج انفرادی صحت کے تناظر اور براہ راست پیمائش کا اندازہ لگا سکتا ہے۔"}],"copyLanguage":"ur","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"tr":{"name":"Vücut Suyu Hesaplayıcı","title":"Vücut Suyu Hesaplayıcı | UsefulVerse","description":"Yayınlanan Watson denklemlerini kullanarak yetişkinlerin toplam vücut suyunu tahmin edin.\nÜcretsiz, yerel ve kullanım sınırı yok;\nhidrasyon testi değil.","intro":"Yayınlanmış bir antropometrik denklemi kullanarak yetişkin yaşı, boyu ve kilosuna göre toplam vücut suyunu tahmin edin.\nTahmini litre cinsinden ve girilen vücut kütlesinin payı olarak görün.","howQuestion":"Toplam vücut suyu nasıl tahmin edilir?","howAnswer":"Watson denklemi değişkenlerinden birini seçin, yetişkin yaşını, boyunu ve kilosunu girin ve hesaplayın.\nSonuç, doğrudan bir ölçüm değil, nüfusa dayalı bir tahmindir.","privacyQuestion":"Ölçümlerim yüklendi mi?","privacyAnswer":"Hayır. Hesaplama bu tarayıcıda yerel olarak çalışır ve değerler bu araç tarafından yüklenmez veya kaydedilmez.","fields":{"equation":"Watson denklemi varyantı","watsonMale":"Erkek denklemi","watsonFemale":"Kadın denklemi","age":"Yaş (yıl; yetişkinler 18-100)","height":"Yükseklik","heightUnit":"Yükseklik birimi","weight":"Ağırlık","weightUnit":"Ağırlık birimi","centimeters":"Santimetre (cm)","inches":"İnç (inç)","kilograms":"Kilogram (kg)","pounds":"Pound (lb)","accuracyNote":"Yalnızca tahmin;\nsıvı alımını ölçmez veya size ne kadar içmeniz gerektiğini söylemez.\nWatson'ın 1980 yetişkin denklemleri, kaynak verilerinden erkek/kadın kategorilerini kullanıyor ve her kişiye veya nüfusa uymayabilir.\nKüçükler, hamilelik, diyaliz, ödem, tanı veya klinik kararlar için uygun değildir.\nSağlıkla ilgili sorularınız için kalifiye bir klinisyene danışın.","resultLiters":"Tahmini toplam vücut suyu","resultPercent":"Vücut kütlesinin yaklaşık payı","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"Tahmini hesapla","example":"Bir örnek deneyin","reset":"Temizle","result":"Tahmin"},"messages":{"calculated":"Tahmin hesaplandı.","checkInputs":"Yetişkin yaşını, boyunu, kilosunu ve seçilen birimleri kontrol edin."},"additionalFaqs":[{"question":"Bu bir hidrasyon testi mi yoksa dehidrasyon testi mi?","answer":"Hayır. Bir nüfus denkleminden toplam vücut suyunu tahmin eder.\nHidrasyon durumunu ölçemez veya dehidrasyonu teşhis edemez."},{"question":"Yüzde ne anlama geliyor?","answer":"1 litre su yaklaşık 1 kilogram olarak kabul edildiğinde litrenin girilen vücut kütlesine bölünmesiyle hesaplanır.\nBu bir hedef ya da sağlıklı aralıkta bir puan değil."},{"question":"Kararlar için bu tahmini kimler kullanmamalıdır?","answer":"Çocuklara, hamileliğe, diyaliz, ödem veya klinik kararlara yönelik değildir.\nBir klinisyen bireysel sağlık bağlamını değerlendirebilir ve doğrudan ölçümler yapabilir."}],"copyLanguage":"tr","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"vi":{"name":"Máy tính lượng nước trong cơ thể","title":"Máy tính lượng nước trong cơ thể | UsefulVerse","description":"Ước tính tổng lượng nước trong cơ thể người trưởng thành bằng các phương trình Watson đã công bố.\nMiễn phí, cục bộ và không giới hạn mức sử dụng;\nkhông…","intro":"Ước tính tổng lượng nước trong cơ thể theo độ tuổi, chiều cao và cân nặng của người trưởng thành bằng phương trình nhân trắc học đã được công bố.\nXem ước tính tính bằng lít và phần trăm khối lượng cơ thể đã nhập.","howQuestion":"Tổng lượng nước trong cơ thể được ước tính như thế nào?","howAnswer":"Chọn một trong các biến thể của phương trình Watson, nhập tuổi, chiều cao và cân nặng của người trưởng thành rồi tính toán.\nKết quả là ước tính dựa trên dân số, không phải là phép đo trực tiếp.","privacyQuestion":"Số đo của tôi có được tải lên không?","privacyAnswer":"Không. Phép tính chạy cục bộ trong trình duyệt này và các giá trị không được công cụ này tải lên hoặc lưu.","fields":{"equation":"Biến thể phương trình Watson","watsonMale":"Phương trình nam","watsonFemale":"Phương trình nữ","age":"Tuổi (năm; người lớn 18–100)","height":"Chiều cao","heightUnit":"Đơn vị chiều cao","weight":"Trọng lượng","weightUnit":"Đơn vị trọng lượng","centimeters":"Cm (cm)","inches":"Inch (trong)","kilograms":"Kilôgam (kg)","pounds":"Bảng Anh (lb)","accuracyNote":"Chỉ ước tính;\nnó không đo lượng nước hoặc cho bạn biết cần uống bao nhiêu.\nCác phương trình dành cho người lớn năm 1980 của Watson sử dụng các danh mục nam/nữ từ dữ liệu nguồn của họ và có thể không phù hợp với mọi người hoặc mọi nhóm dân cư.\nKhông dành cho trẻ vị thành niên, mang thai, lọc máu, phù nề, chẩn đoán hoặc quyết định lâm sàng.\nĐối với các câu hỏi về sức khỏe, hãy hỏi bác sĩ lâm sàng có trình độ.","resultLiters":"Tổng lượng nước cơ thể ước tính","resultPercent":"Tỷ lệ khối lượng cơ thể gần đúng","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"Tính toán ước tính","example":"Hãy thử một ví dụ","reset":"Xóa\nƯớc tính","result":"Ước lượng"},"messages":{"calculated":"Đã tính toán ước tính.","checkInputs":"Kiểm tra độ tuổi, chiều cao, cân nặng của người lớn và các đơn vị đã chọn."},"additionalFaqs":[{"question":"Đây có phải là xét nghiệm hydrat hóa hay khử nước không?","answer":"Không. Nó ước tính tổng lượng nước cơ thể từ một phương trình dân số.\nNó không thể đo tình trạng hydrat hóa hoặc chẩn đoán tình trạng mất nước."},{"question":"Tỷ lệ phần trăm có ý nghĩa gì?","answer":"Ước tính lít chia cho khối lượng cơ thể nhập vào, coi 1 lít nước là khoảng 1 kg.\nNó không phải là một mục tiêu hay một điểm số ở mức lành mạnh."},{"question":"Ai không nên sử dụng ước tính này để đưa ra quyết định?","answer":"Nó không dành cho trẻ em, mang thai, lọc máu, phù nề hoặc các quyết định lâm sàng.\nBác sĩ lâm sàng có thể đánh giá bối cảnh sức khỏe cá nhân và các phép đo trực tiếp."}],"copyLanguage":"vi","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"it":{"name":"Calcolatore dell'acqua corporea","title":"Calcolatore dell'acqua corporea | UsefulVerse","description":"Stima dell'acqua corporea totale di un adulto con le equazioni di Watson pubblicate.\nGratuito, locale e senza limiti di utilizzo;\nnon un test di idratazione.","intro":"Stimare l'acqua corporea totale dall'età adulta, altezza e peso utilizzando un'equazione antropometrica pubblicata.\nVisualizza la stima in litri e come percentuale della massa corporea inserita.","howQuestion":"Come viene stimata l'acqua corporea totale?","howAnswer":"Scegli una delle varianti dell'equazione di Watson, inserisci l'età, l'altezza e il peso dell'adulto, quindi calcola.\nIl risultato è una stima basata sulla popolazione, non una misurazione diretta.","privacyQuestion":"Le mie misure sono caricate?","privacyAnswer":"No. Il calcolo viene eseguito localmente in questo browser e i valori non vengono caricati o salvati da questo strumento.","fields":{"equation":"Variante dell'equazione di Watson","watsonMale":"Equazione maschile","watsonFemale":"Equazione femminile","age":"Età (anni; adulti 18-100)","height":"Altezza","heightUnit":"Unità di altezza","weight":"Peso","weightUnit":"Unità di peso","centimeters":"Centimetri (cm)","inches":"pollici (pollici)","kilograms":"Chilogrammi (kg)","pounds":"Libbre (libbre)","accuracyNote":"Solo preventivo;\nnon misura l'idratazione né ti dice quanto bere.\nLe equazioni degli adulti di Watson del 1980 utilizzano categorie maschili/femminili dai dati di origine e potrebbero non adattarsi a ogni persona o popolazione.\nNon per minori, gravidanza, dialisi, edema, diagnosi o decisioni cliniche.\nPer domande sulla salute, chiedere a un medico qualificato.","resultLiters":"Acqua corporea totale stimata","resultPercent":"Quota approssimativa della massa corporea","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"Calcola preventivo","example":"Prova un esempio","reset":"Cancella","result":"Stima"},"messages":{"calculated":"Stima calcolata.","checkInputs":"Controlla l'età, l'altezza, il peso e le unità selezionate dell'adulto."},"additionalFaqs":[{"question":"È un test di idratazione o disidratazione?","answer":"No. Stima l'acqua corporea totale da un'equazione della popolazione.\nNon può misurare lo stato di idratazione o diagnosticare la disidratazione."},{"question":"Cosa significa la percentuale?","answer":"Si calcolano i litri divisi per la massa corporea inserita, considerando 1 litro d'acqua come circa 1 chilogrammo.\nNon è un obiettivo o un punteggio accettabile."},{"question":"Chi non dovrebbe utilizzare questa stima per le decisioni?","answer":"Non è destinato a bambini, gravidanza, dialisi, edema o decisioni cliniche.\nUn medico può valutare il contesto sanitario individuale e dirigere le misurazioni."}],"copyLanguage":"it","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"zh_tw":{"name":"身體水分計算器","title":"身體水分計算器 | UsefulVerse","description":"使用已發表的 Watson 方程式估算成人體內總水分。免費、本地且無使用限制；不是水合測試。","intro":"使用已發表的人體測量方程式根據成人年齡、身高和體重估算體內水分總量。查看以公升為單位的估計值以及輸入的體重的百分比。","howQuestion":"體內總水分是如何估算的？","howAnswer":"選擇 Watson 方程式變體之一，輸入成人年齡、身高和體重，然後進行計算。結果是基於人口的估計，而不是直接測量。","privacyQuestion":"我的測量結果上傳了嗎？","privacyAnswer":"否。計算在此瀏覽器中本地運行，並且該工具不會上傳或保存值。","fields":{"equation":"Watson 方程式變體","watsonMale":"男方程","watsonFemale":"女方程","age":"年齡（歲；成人 18–100）","height":"身高","heightUnit":"高度單位","weight":"重量","weightUnit":"重量單位","centimeters":"公分 (cm)","inches":"吋 (in)","kilograms":"公斤 (kg)","pounds":"磅 (lb)","accuracyNote":"僅估算；它不會測量水合作用或告訴您喝多少水。 Watson 的 1980 年成人方程式使用來源資料中的男性/女性類別，可能不適合每個人或族群。不適用於未成年、懷孕、透析、水腫、診斷或臨床決策。對於健康問題，請諮詢合格的臨床醫生。","resultLiters":"估計體內總水分","resultPercent":"體重的大約比例","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"計算估算","example":"試試一個例子","reset":"清除","result":"預估"},"messages":{"calculated":"計算得出的估計值。","checkInputs":"检查成人年龄、身高、体重和所选单位。"},"additionalFaqs":[{"question":"这是水合或脱水测试吗？","answer":"否。它根據人口方程式估算體內總水分。它無法測量水合狀態或診斷脫水。"},{"question":"百分比是什麼意思？","answer":"估計升數除以輸入的體重，將 1 公升水視為約 1 公斤。它不是目標或健康範圍分數。"},{"question":"誰不應該使用此估計進行決策？","answer":"不適用於兒童、懷孕、透析、水腫或臨床決策。臨床醫生可以評估個人健康狀況並進行直接測量。"}],"copyLanguage":"zh_tw","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"bg":{"name":"Калкулатор за вода в тялото","title":"Калкулатор за вода в тялото | UsefulVerse","description":"Изчислете общата телесна вода на възрастен с публикуваните уравнения на Watson.\nБезплатно, локално и без ограничение за използване;\nне е тест за хидратация.","intro":"Оценете общата телесна вода от зряла възраст, височина и тегло, като използвате публикувано антропометрично уравнение.\nВижте оценката в литри и като дял от въведената телесна маса.","howQuestion":"Как се изчислява общата вода в тялото?","howAnswer":"Изберете един от вариантите на уравнението на Watson, въведете зряла възраст, височина и тегло, след което изчислете.\nРезултатът е оценка, базирана на населението, а не директно измерване.","privacyQuestion":"Моите измервания качени ли са?","privacyAnswer":"Не. Изчислението се изпълнява локално в този браузър и стойностите не се качват или запазват от този инструмент.","fields":{"equation":"Вариант на уравнението на Уотсън","watsonMale":"Мъжко уравнение","watsonFemale":"Женско уравнение","age":"Възраст (години; възрастни 18–100)","height":"Височина","heightUnit":"Единица за височина","weight":"Тегло","weightUnit":"Единица за тегло","centimeters":"Сантиметри (cm)","inches":"инча (инча)","kilograms":"килограма (кг)","pounds":"паунда (lb)","accuracyNote":"Само прогноза;\nне измерва хидратацията и не ви казва колко да пиете.\nУравненията за възрастни на Watson от 1980 г. използват категории мъже/жени от техните изходни данни и може да не отговарят на всеки човек или население.\nНе е за непълнолетни, бременност, диализа, отоци, диагноза или клинични решения.\nЗа здравословни въпроси попитайте квалифициран клиницист.","resultLiters":"Очаквана обща вода в тялото","resultPercent":"Приблизителен дял от телесната маса","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"Изчислете оценка","example":"Опитайте пример","reset":"Ясно","result":"Оценка"},"messages":{"calculated":"Изчислена оценка.","checkInputs":"Проверете възрастта, височината, теглото и избраните единици."},"additionalFaqs":[{"question":"Това тест за хидратация или дехидратация ли е?","answer":"Не. Той оценява общата телесна вода от уравнение за населението.\nНе може да измерва състоянието на хидратация или да диагностицира дехидратация."},{"question":"Какво означава процентът?","answer":"Изчислява литри, разделени на въведената телесна маса, като 1 литър вода се третира като около 1 килограм.\nТова не е целеви или здравословен резултат."},{"question":"Кой не трябва да използва тази оценка за вземане на решения?","answer":"Не е предназначен за деца, бременност, диализа, отоци или клинични решения.\nКлиницистът може да оцени индивидуалния здравен контекст и директни измервания."}],"copyLanguage":"bg","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"ca":{"name":"Calculadora d'aigua corporal","title":"Calculadora d'aigua corporal | UsefulVerse","description":"Estimar l'aigua corporal total de l'adult amb les equacions de Watson publicades.\nGratuït, local i sense límit d'ús;\nno és una prova d'hidratació.","intro":"Estimar l'aigua corporal total a partir de l'edat adulta, l'alçada i el pes mitjançant una equació antropomètrica publicada.\nConsulteu l'estimació en litres i com a proporció de la massa corporal introduïda.","howQuestion":"Com s'estima l'aigua corporal total?","howAnswer":"Trieu una de les variants de l'equació de Watson, introduïu l'edat adulta, l'alçada i el pes i, a continuació, feu el càlcul.\nEl resultat és una estimació basada en la població, no una mesura directa.","privacyQuestion":"S'han penjat les meves mesures?","privacyAnswer":"No. El càlcul s'executa localment en aquest navegador i aquesta eina no carrega ni desa els valors.","fields":{"equation":"Variant de l'equació de Watson","watsonMale":"Equació masculina","watsonFemale":"Equació femenina","age":"Edat (anys; adults de 18 a 100)","height":"Alçada","heightUnit":"Unitat d'alçada","weight":"Pes","weightUnit":"Unitat de pes","centimeters":"centímetres (cm)","inches":"polzades (polzades)","kilograms":"quilograms (kg)","pounds":"lliures (lb)","accuracyNote":"Només pressupost;\nno mesura la hidratació ni et diu quant beure.\nLes equacions d'adults de Watson de 1980 utilitzen categories masculina/dona de les seves dades d'origen i és possible que no s'adaptin a totes les persones o població.\nNo per a menors, embaràs, diàlisi, edemes, diagnòstic o decisions clíniques.\nPer a preguntes de salut, pregunteu a un metge qualificat.","resultLiters":"Estimació d'aigua corporal total","resultPercent":"Part aproximada de la massa corporal","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"Calcula pressupost","example":"Proveu un exemple","reset":"Clar","result":"Estimació"},"messages":{"calculated":"Estimació calculada.","checkInputs":"Consulta l'edat adulta, l'alçada, el pes i les unitats seleccionades."},"additionalFaqs":[{"question":"És una prova d'hidratació o deshidratació?","answer":"No. Estima l'aigua corporal total a partir d'una equació de població.\nNo pot mesurar l'estat d'hidratació ni diagnosticar la deshidratació."},{"question":"Què vol dir el percentatge?","answer":"S'estima que els litres es divideixen per la massa corporal introduïda, tractant 1 litre d'aigua com a aproximadament 1 quilogram.\nNo és un objectiu ni una puntuació de rang saludable."},{"question":"Qui no hauria d'utilitzar aquesta estimació per prendre decisions?","answer":"No està pensat per a nens, embaràs, diàlisi, edemes o decisions clíniques.\nUn metge pot avaluar el context de salut individual i mesurar directament."}],"copyLanguage":"ca","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"nl":{"name":"Lichaamswatercalculator","title":"Lichaamswatercalculator | UsefulVerse","description":"Schat het totale lichaamswater van volwassenen met de gepubliceerde Watson-vergelijkingen.\nGratis, lokaal en geen gebruikslimiet;\ngeen hydratatietest.","intro":"Schat het totale lichaamswater vanaf volwassen leeftijd, lengte en gewicht met behulp van een gepubliceerde antropometrische vergelijking.\nBekijk de schatting in liters en als percentage van de ingevoerde lichaamsmassa.","howQuestion":"Hoe wordt het totale lichaamswater geschat?","howAnswer":"Kies een van de varianten van de Watson-vergelijking, voer de volwassen leeftijd, lengte en gewicht in en bereken vervolgens.\nHet resultaat is een populatiegebaseerde schatting, geen directe meting.","privacyQuestion":"Worden mijn metingen geüpload?","privacyAnswer":"Nee. De berekening wordt lokaal in deze browser uitgevoerd en de waarden worden niet door deze tool geüpload of opgeslagen.","fields":{"equation":"Watson-vergelijkingsvariant","watsonMale":"Mannelijke vergelijking","watsonFemale":"Vrouwelijke vergelijking","age":"Leeftijd (jaren; volwassenen 18-100)","height":"Hoogte","heightUnit":"Hoogte-eenheid","weight":"Gewicht","weightUnit":"Gewichtseenheid","centimeters":"Centimeter (cm)","inches":"Inch (inch)","kilograms":"Kilogram (kg)","pounds":"Pond (lb)","accuracyNote":"Alleen schatting;\nhet meet niet de hydratatie en vertelt u niet hoeveel u moet drinken.\nWatsons vergelijkingen voor volwassenen uit 1980 gebruiken de categorieën man/vrouw uit hun brongegevens en passen mogelijk niet bij elke persoon of populatie.\nNiet voor minderjarigen, zwangerschap, dialyse, oedeem, diagnose of klinische beslissingen.\nVoor gezondheidsvragen kunt u terecht bij een gekwalificeerde arts.","resultLiters":"Geschat totaal lichaamswater","resultPercent":"Geschat aandeel van de lichaamsmassa","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"Schatting berekenen","example":"Probeer een voorbeeld","reset":"Helder","result":"Schatting"},"messages":{"calculated":"Schatting berekend.","checkInputs":"Controleer de leeftijd, lengte, gewicht en geselecteerde eenheden van volwassenen."},"additionalFaqs":[{"question":"Is dit een hydratatie- of dehydratatietest?","answer":"Nee. Het schat het totale lichaamswater op basis van een populatievergelijking.\nHet kan de hydratatiestatus niet meten of uitdroging diagnosticeren."},{"question":"Wat betekent het percentage?","answer":"Er wordt geschat dat het aantal liters wordt gedeeld door de ingevoerde lichaamsmassa, waarbij 1 liter water wordt beschouwd als ongeveer 1 kilogram.\nHet is geen streefcijfer of een score op een gezond bereik."},{"question":"Wie mag deze schatting niet gebruiken bij beslissingen?","answer":"Het is niet bedoeld voor kinderen, zwangerschap, dialyse, oedeem of klinische beslissingen.\nEen arts kan de individuele gezondheidscontext en directe metingen beoordelen."}],"copyLanguage":"nl","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"el":{"name":"Υπολογιστής νερού σώματος","title":"Υπολογιστής νερού σώματος | UsefulVerse","description":"Υπολογίστε το συνολικό νερό του σώματος των ενηλίκων με τις δημοσιευμένες εξισώσεις Watson.\nΔωρεάν, τοπικό και χωρίς όριο χρήσης.\nόχι τεστ ενυδάτωσης.","intro":"Υπολογίστε το συνολικό νερό του σώματος από την ενήλικη ηλικία, το ύψος και το βάρος χρησιμοποιώντας μια δημοσιευμένη ανθρωπομετρική εξίσωση.\nΔείτε την εκτίμηση σε λίτρα και ως μερίδιο της εισαγόμενης μάζας σώματος.","howQuestion":"Πώς υπολογίζεται το συνολικό νερό του σώματος;","howAnswer":"Επιλέξτε μία από τις παραλλαγές της εξίσωσης Watson, εισαγάγετε την ηλικία, το ύψος και το βάρος του ενήλικα και μετά υπολογίστε.\nΤο αποτέλεσμα είναι μια εκτίμηση με βάση τον πληθυσμό, όχι μια άμεση μέτρηση.","privacyQuestion":"Έχουν μεταφορτωθεί οι μετρήσεις μου;","privacyAnswer":"Όχι. Ο υπολογισμός εκτελείται τοπικά σε αυτό το πρόγραμμα περιήγησης και οι τιμές δεν μεταφορτώνονται ούτε αποθηκεύονται από αυτό το εργαλείο.","fields":{"equation":"Παραλλαγή εξίσωσης Watson","watsonMale":"Εξίσωση αρσενικού","watsonFemale":"Γυναικεία εξίσωση","age":"Ηλικία (έτη, ενήλικες 18–100)","height":"Ύψ","heightUnit":"Μονάδα ύψους","weight":"Βάρος","weightUnit":"Μονάδα βάρους","centimeters":"Εκατοστά (cm)","inches":"ίντσες (in)","kilograms":"κιλά (kg)","pounds":"Λίρες (λίβρες)","accuracyNote":"Εκτίμηση μόνο.\nδεν μετράει την ενυδάτωση ούτε σας λέει πόσο να πιείτε.\nΟι εξισώσεις ενηλίκων του Watson του 1980 χρησιμοποιούν κατηγορίες ανδρών/θηλυκών από τα δεδομένα πηγής τους και μπορεί να μην ταιριάζουν σε κάθε άτομο ή πληθυσμό.\nΌχι για ανηλίκους, εγκυμοσύνη, αιμοκάθαρση, οίδημα, διάγνωση ή κλινικές αποφάσεις.\nΓια ερωτήσεις υγείας, ρωτήστε έναν εξειδικευμένο κλινικό ιατρό.","resultLiters":"Εκτιμώμενο συνολικό νερό στο σώμα","resultPercent":"Κατά προσέγγιση μερίδιο μάζας σώματος","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"Υπολογισμός εκτίμησης","example":"Δοκιμάστε ένα παράδειγμα","reset":"Καθαρισμός","result":"Εκτίμηση"},"messages":{"calculated":"Υπολογίστηκε εκτίμηση.","checkInputs":"Ελέγξτε την ηλικία, το ύψος, το βάρος και τις επιλεγμένες μονάδες ενηλίκων."},"additionalFaqs":[{"question":"Είναι αυτό ένα τεστ ενυδάτωσης ή αφυδάτωσης;","answer":"Όχι. Εκτιμά το συνολικό νερό του σώματος από μια εξίσωση πληθυσμού.\nΔεν μπορεί να μετρήσει την κατάσταση ενυδάτωσης ή να διαγνώσει την αφυδάτωση."},{"question":"Τι σημαίνει το ποσοστό;","answer":"Υπολογίζεται ότι τα λίτρα διαιρούνται με την εισαγόμενη μάζα σώματος, αντιμετωπίζοντας 1 λίτρο νερού ως περίπου 1 κιλό.\nΔεν είναι στόχος ή βαθμολογία υγιούς εύρους."},{"question":"Ποιος δεν πρέπει να χρησιμοποιεί αυτήν την εκτίμηση για αποφάσεις;","answer":"Δεν προορίζεται για παιδιά, εγκυμοσύνη, αιμοκάθαρση, οίδημα ή κλινικές αποφάσεις.\nΈνας κλινικός ιατρός μπορεί να αξιολογήσει το ατομικό πλαίσιο υγείας και άμεσες μετρήσεις."}],"copyLanguage":"el","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"ms":{"name":"Kalkulator Air Badan","title":"Kalkulator Air Badan | UsefulVerse","description":"Anggarkan jumlah air badan dewasa dengan persamaan Watson yang diterbitkan.\nPercuma, tempatan dan tiada had penggunaan;\nbukan ujian penghidratan.","intro":"Anggarkan jumlah air badan daripada umur, ketinggian dan berat dewasa menggunakan persamaan antropometrik yang diterbitkan.\nLihat anggaran dalam liter dan sebagai bahagian jisim badan yang dimasukkan.","howQuestion":"Bagaimanakah jumlah air badan dianggarkan?","howAnswer":"Pilih salah satu daripada varian persamaan Watson, masukkan umur dewasa, tinggi dan berat, kemudian hitung.\nHasilnya ialah anggaran berasaskan populasi, bukan ukuran langsung.","privacyQuestion":"Adakah ukuran saya dimuat naik?","privacyAnswer":"Tidak. Pengiraan berjalan secara setempat dalam penyemak imbas ini dan nilai tidak dimuat naik atau disimpan oleh alat ini.","fields":{"equation":"varian persamaan Watson","watsonMale":"Persamaan lelaki","watsonFemale":"Persamaan perempuan","age":"Umur (tahun; dewasa 18–100)","height":"Tinggi","heightUnit":"Unit ketinggian","weight":"Berat","weightUnit":"Unit berat","centimeters":"Sentimeter (cm)","inches":"Inci (dalam)","kilograms":"Kilogram (kg)","pounds":"Pound (lb)","accuracyNote":"Anggaran sahaja;\nia tidak mengukur penghidratan atau memberitahu anda berapa banyak yang perlu diminum.\nPersamaan dewasa Watson 1980 menggunakan kategori lelaki/perempuan daripada data sumbernya dan mungkin tidak sesuai dengan setiap orang atau populasi.\nBukan untuk kanak-kanak bawah umur, kehamilan, dialisis, edema, diagnosis atau keputusan klinikal.\nUntuk soalan kesihatan, tanya doktor yang bertauliah.","resultLiters":"Anggaran jumlah air badan","resultPercent":"Bahagian anggaran jisim badan","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"Kira anggaran","example":"Cuba contoh","reset":"Jelas","result":"Anggaran"},"messages":{"calculated":"Anggaran dikira.","checkInputs":"Semak umur dewasa, tinggi, berat dan unit yang dipilih."},"additionalFaqs":[{"question":"Adakah ini ujian penghidratan atau dehidrasi?","answer":"Tidak. Ia menganggarkan jumlah air badan daripada persamaan populasi.\nIa tidak dapat mengukur status penghidratan atau mendiagnosis dehidrasi."},{"question":"Apakah maksud peratusan?","answer":"Dianggarkan liter dibahagikan dengan jisim badan yang dimasukkan, merawat 1 liter air sebagai kira-kira 1 kilogram.\nIa bukan sasaran atau skor jarak sihat."},{"question":"Siapa yang tidak sepatutnya menggunakan anggaran ini untuk membuat keputusan?","answer":"Ia tidak bertujuan untuk kanak-kanak, kehamilan, dialisis, edema atau keputusan klinikal.\nSeorang doktor boleh menilai konteks kesihatan individu dan pengukuran langsung."}],"copyLanguage":"ms","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"pl":{"name":"Kalkulator wody w organizmie","title":"Kalkulator wody w organizmie | UsefulVerse","description":"Oszacuj całkowitą zawartość wody w organizmie osoby dorosłej za pomocą opublikowanych równań Watsona.\nBezpłatny, lokalny i bez limitu użytkowania;\nnie…","intro":"Oszacuj całkowitą zawartość wody w organizmie w odniesieniu do wieku dorosłego, wzrostu i masy ciała, korzystając z opublikowanego równania antropometrycznego.\nZobacz szacunkową wartość w litrach i jako udział wprowadzonej masy ciała.","howQuestion":"Jak szacuje się całkowitą zawartość wody w organizmie?","howAnswer":"Wybierz jeden z wariantów równania Watsona, wprowadź wiek, wzrost i wagę osoby dorosłej, a następnie wykonaj obliczenia.\nRezultatem jest szacunek oparty na populacji, a nie bezpośredni pomiar.","privacyQuestion":"Czy moje pomiary zostały przesłane?","privacyAnswer":"Nie. Obliczenia są wykonywane lokalnie w tej przeglądarce, a wartości nie są przesyłane ani zapisywane przez to narzędzie.","fields":{"equation":"Wariant równania Watsona","watsonMale":"Równanie męskie","watsonFemale":"Równanie żeńskie","age":"Wiek (lata; dorośli 18–100)","height":"Wysokość","heightUnit":"Jednostka wysokości","weight":"Waga","weightUnit":"Jednostka masy","centimeters":"Centymetry (cm)","inches":"Cale (cale)","kilograms":"Kilogramy (kg)","pounds":"Funty (funty)","accuracyNote":"Tylko szacunkowo;\nnie mierzy nawodnienia ani nie mówi, ile wypić.\nRównania Watsona dla dorosłych z 1980 r. wykorzystują kategorie męskie/żeńskie z danych źródłowych i mogą nie pasować do każdej osoby lub populacji.\nNie dotyczy osób nieletnich, ciąży, dializ, obrzęków, diagnozy ani decyzji klinicznych.\nW przypadku pytań zdrowotnych należy zwrócić się do wykwalifikowanego lekarza.","resultLiters":"Szacunkowa całkowita ilość wody w organizmie","resultPercent":"Przybliżony udział masy ciała","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"Oblicz oszacowanie","example":"Wypróbuj przykład","reset":"Jasne","result":"Oszacowanie"},"messages":{"calculated":"Obliczono szacunkowo.","checkInputs":"Sprawdź wiek osoby dorosłej, wzrost, wagę i wybrane jednostki."},"additionalFaqs":[{"question":"Czy to test nawodnienia czy odwodnienia?","answer":"Nie. Szacuje całkowitą ilość wody w organizmie na podstawie równania populacji.\nNie jest w stanie zmierzyć stanu nawodnienia ani zdiagnozować odwodnienia."},{"question":"Co oznacza procent?","answer":"Oblicza się, że litry są podzielone przez wprowadzoną masę ciała, co oznacza, że ​​1 litr wody równa się około 1 kilogramowi.\nNie jest to wynik docelowy ani zdrowy zakres."},{"question":"Kto nie powinien wykorzystywać tego oszacowania przy podejmowaniu decyzji?","answer":"Nie jest przeznaczony dla dzieci, ciąży, dializ, obrzęków ani decyzji klinicznych.\nLekarz może ocenić indywidualny kontekst zdrowotny i dokonać bezpośrednich pomiarów."}],"copyLanguage":"pl","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"sv":{"name":"Kroppsvattenräknare","title":"Kroppsvattenräknare | UsefulVerse","description":"Beräkna vuxens totala kroppsvatten med de publicerade Watson-ekvationerna.\nGratis, lokal och ingen användningsgräns;\ninte ett vätsketest.","intro":"Beräkna totalt kroppsvatten från vuxen ålder, längd och vikt med hjälp av en publicerad antropometrisk ekvation.\nSe uppskattningen i liter och som andel av inmatad kroppsmassa.","howQuestion":"Hur uppskattas det totala kroppsvattnet?","howAnswer":"Välj en av Watsons ekvationsvarianter, ange vuxen ålder, längd och vikt och beräkna sedan.\nResultatet är en populationsbaserad uppskattning, inte en direkt mätning.","privacyQuestion":"Är mina mått uppladdade?","privacyAnswer":"Nej. Beräkningen körs lokalt i den här webbläsaren och värdena laddas inte upp eller sparas av detta verktyg.","fields":{"equation":"Watsons ekvationsvariant","watsonMale":"Manlig ekvation","watsonFemale":"Kvinnlig ekvation","age":"Ålder (år; vuxna 18–100)","height":"Höjd","heightUnit":"Höjdenhet","weight":"Vikt","weightUnit":"Viktenhet","centimeters":"Centimeter (cm)","inches":"tum (tum)","kilograms":"Kilogram (kg)","pounds":"Pund (lb)","accuracyNote":"Endast uppskattning;\nden mäter inte hydrering eller talar om för dig hur mycket du ska dricka.\nWatsons ekvationer för vuxna från 1980 använder manliga/kvinnliga kategorier från deras källdata och kanske inte passar varje person eller befolkning.\nInte för minderåriga, graviditet, dialys, ödem, diagnos eller kliniska beslut.\nFör hälsofrågor, fråga en kvalificerad läkare.","resultLiters":"Uppskattat totalt kroppsvatten","resultPercent":"Ungefärlig andel av kroppsmassan","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"Beräkna uppskattning","example":"Prova ett exempel","reset":"Clear","result":"Uppskattning"},"messages":{"calculated":"Uppskattning beräknad.","checkInputs":"Kontrollera vuxen ålder, längd, vikt och valda enheter."},"additionalFaqs":[{"question":"Är detta ett vätske- eller uttorkningstest?","answer":"Nej. Den uppskattar totalt kroppsvatten från en befolkningsekvation.\nDen kan inte mäta vätskestatus eller diagnostisera uttorkning."},{"question":"Vad betyder procentsatsen?","answer":"Det uppskattas liter dividerat med den angivna kroppsmassan, vilket behandlar 1 liter vatten som cirka 1 kilogram.\nDet är inte ett mål eller ett friskt intervall."},{"question":"Vem ska inte använda denna uppskattning för beslut?","answer":"Den är inte avsedd för barn, graviditet, dialys, ödem eller kliniska beslut.\nEn läkare kan bedöma individuella hälsosammanhang och direkta mätningar."}],"copyLanguage":"sv","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"th":{"name":"เครื่องคำนวณน้ำในร่างกาย","title":"เครื่องคำนวณน้ำในร่างกาย | UsefulVerse","description":"ประมาณปริมาณน้ำในร่างกายของผู้ใหญ่ด้วยสมการวัตสันที่เผยแพร่\nฟรี ในพื้นที่ และไม่มีขีดจำกัดการใช้งาน\nไม่ใช่การทดสอบความชุ่มชื้น","intro":"ประมาณปริมาณน้ำในร่างกายทั้งหมดจากอายุ ส่วนสูงและน้ำหนักของผู้ใหญ่โดยใช้สมการสัดส่วนร่างกายของมนุษย์ที่เผยแพร่\nดูค่าประมาณเป็นลิตรและเป็นส่วนแบ่งของมวลกายที่ป้อน","howQuestion":"ปริมาณน้ำในร่างกายทั้งหมดประมาณไว้อย่างไร?","howAnswer":"เลือกหนึ่งในตัวแปรสมการวัตสัน กรอกอายุ ส่วนสูง และน้ำหนักของผู้ใหญ่ แล้วคำนวณ\nผลลัพธ์คือการประมาณการตามประชากร ไม่ใช่การวัดโดยตรง","privacyQuestion":"อัปโหลดการวัดของฉันแล้วหรือยัง","privacyAnswer":"ไม่ การคำนวณรันภายในเบราว์เซอร์นี้ และเครื่องมือนี้ไม่ได้อัปโหลดหรือบันทึกค่า","fields":{"equation":"ตัวแปรสมการวัตสัน","watsonMale":"สมชาย","watsonFemale":"สมการหญิง","age":"อายุ (ปี ผู้ใหญ่ 18–100 ปี)","height":"ส่วนสูง","heightUnit":"หน่วยความสูง","weight":"น้ำหนัก","weightUnit":"หน่วยน้ำหนัก","centimeters":"เซนติเมตร (ซม.)","inches":"นิ้ว (นิ้ว)","kilograms":"กิโลกรัม (กก.)","pounds":"ปอนด์ (ปอนด์)","accuracyNote":"ประมาณการเท่านั้น;\nมันไม่ได้วัดระดับความชุ่มชื้นหรือบอกคุณว่าควรดื่มมากแค่ไหน\nสมการสำหรับผู้ใหญ่ของวัตสันในปี 1980 ใช้หมวดหมู่ชาย/หญิงจากแหล่งข้อมูล และอาจไม่เหมาะกับทุกคนหรือทุกประชากร\nไม่เหมาะสำหรับผู้เยาว์ การตั้งครรภ์ การล้างไต อาการบวมน้ำ การวินิจฉัย หรือการตัดสินใจทางคลินิก\nสำหรับคำถามด้านสุขภาพ โปรดสอบถามจากแพทย์ที่มีคุณสมบัติเหมาะสม","resultLiters":"ปริมาณน้ำในร่างกายทั้งหมดโดยประมาณ","resultPercent":"ส่วนแบ่งมวลกายโดยประมาณ","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"คำนวณประมาณการ","example":"ลองตัวอย่าง","reset":"เคลียร์","result":"ประมาณการ"},"messages":{"calculated":"คำนวณแล้ว","checkInputs":"ตรวจสอบอายุ ส่วนสูง น้ำหนัก และหน่วยที่เลือกของผู้ใหญ่"},"additionalFaqs":[{"question":"นี่เป็นการทดสอบภาวะขาดน้ำหรือภาวะขาดน้ำหรือไม่","answer":"ไม่ เป็นค่าประมาณปริมาณน้ำในร่างกายทั้งหมดจากสมการประชากร\nไม่สามารถวัดสถานะความชุ่มชื้นหรือวินิจฉัยภาวะขาดน้ำได้"},{"question":"เปอร์เซ็นต์หมายถึงอะไร?","answer":"ประมาณลิตรหารด้วยมวลกายที่ป้อน โดยบำบัดน้ำ 1 ลิตรได้ประมาณ 1 กิโลกรัม\nไม่ใช่เป้าหมายหรือคะแนนช่วงที่ดี"},{"question":"ใครไม่ควรใช้ค่าประมาณนี้ในการตัดสินใจ?","answer":"ไม่ได้มีไว้สำหรับเด็ก การตั้งครรภ์ การล้างไต อาการบวมน้ำ หรือการตัดสินใจทางคลินิก\nแพทย์สามารถประเมินบริบทด้านสุขภาพของแต่ละบุคคลและการวัดผลโดยตรง\nอนุมัติแล้ว"}],"copyLanguage":"th","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"uk":{"name":"Калькулятор води в організмі","title":"Калькулятор води в організмі | UsefulVerse","description":"Оцініть загальну кількість води в організмі дорослої людини за допомогою опублікованих рівнянь Ватсона.\nБезкоштовний, локальний і без обмеження…","intro":"Оцініть загальну кількість води в організмі за дорослим віком, зростом і вагою за допомогою опублікованого антропометричного рівняння.\nПерегляньте оцінку в літрах і як частку введеної маси тіла.","howQuestion":"Як оцінюється загальна вода в організмі?","howAnswer":"Виберіть один із варіантів рівняння Вотсона, введіть дорослий вік, зріст і вагу, а потім обчисліть.\nРезультат є оцінкою на основі населення, а не прямим вимірюванням.","privacyQuestion":"Чи завантажено мої вимірювання?","privacyAnswer":"Ні. Розрахунок виконується локально в цьому браузері, і значення не завантажуються та не зберігаються цим інструментом.","fields":{"equation":"Варіант рівняння Ватсона","watsonMale":"Чоловіче рівняння","watsonFemale":"Жіноче рівняння","age":"Вік (років; дорослі 18–100)","height":"Висота","heightUnit":"Одиниця висоти","weight":"Вага","weightUnit":"Одиниця ваги","centimeters":"Сантиметри (см)","inches":"Дюйми (дюйми)","kilograms":"Кілограми (кг)","pounds":"Фунтів (фунтів)","accuracyNote":"Тільки оцінка;\nвін не вимірює рівень гідратації та не повідомляє вам, скільки пити.\nРівняння для дорослих Уотсона 1980 року використовують категорії чоловік/жінка з їхніх вихідних даних і можуть не відповідати кожній людині чи групі населення.\nНе для неповнолітніх, вагітності, діалізу, набряків, діагностики чи клінічних рішень.\nЗ питань здоров’я зверніться до кваліфікованого клініциста.","resultLiters":"Розрахункова загальна кількість води в організмі","resultPercent":"Приблизна частка маси тіла","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"Розрахувати кошторис","example":"Спробуйте приклад","reset":"Очистити","result":"Оцінка"},"messages":{"calculated":"Оцінка розрахована.","checkInputs":"Перевірте дорослий вік, зріст, вагу та вибрані одиниці."},"additionalFaqs":[{"question":"Це тест на гідратацію чи дегідратацію?","answer":"Ні. Він оцінює загальну кількість води в організмі за рівнянням населення.\nВін не може виміряти рівень гідратації або діагностувати зневоднення."},{"question":"Що означає відсоток?","answer":"Оцінка літрів, поділена на введену масу тіла, розглядаючи 1 літр води приблизно як 1 кілограм.\nЦе не цільовий чи здоровий результат."},{"question":"Кому не слід використовувати цю оцінку для прийняття рішень?","answer":"Не призначений для дітей, вагітності, діалізу, набряків або клінічних рішень.\nКлініцист може оцінити індивідуальний стан здоров’я та провести прямі вимірювання."}],"copyLanguage":"uk","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"sw":{"name":"Kikokotoo cha Maji ya Mwili","title":"Kikokotoo cha Maji ya Mwili | UsefulVerse","description":"Kadiria jumla ya maji ya mwili kwa watu wazima na milinganyo iliyochapishwa ya Watson.\nBure, ndani na hakuna kikomo cha matumizi;\nsio mtihani wa unyevu.","intro":"Kadiria jumla ya maji mwilini kutoka kwa watu wazima, urefu na uzito kwa kutumia mlinganyo wa kianthropometriki uliochapishwa.\nTazama makadirio katika lita na kama sehemu ya misa ya mwili iliyoingia.","howQuestion":"Je, jumla ya maji ya mwili inakadiriwaje?","howAnswer":"Chagua mojawapo ya vibadala vya mlinganyo wa Watson, weka umri, urefu na uzito wa watu wazima, kisha ukokotoe.\nMatokeo yake ni makadirio kulingana na idadi ya watu, sio kipimo cha moja kwa moja.","privacyQuestion":"Je, vipimo vyangu vimepakiwa?","privacyAnswer":"Hapana. Hesabu inaendeshwa ndani ya kivinjari hiki na thamani hazijapakiwa au kuhifadhiwa na zana hii.","fields":{"equation":"lahaja ya mlinganyo wa Watson","watsonMale":"Mlinganyo wa kiume","watsonFemale":"Mlinganyo wa kike","age":"Umri (miaka; watu wazima 18–100)","height":"Urefu","heightUnit":"Kitengo cha urefu","weight":"Uzito","weightUnit":"Kitengo cha uzito","centimeters":"(cm)\nInchi","inches":"(ndani)","kilograms":"Kilo (kg)\nPauni","pounds":"(lb)","accuracyNote":"Kadiria pekee;\nhaipimi unyevu au kukuambia ni kiasi gani cha kunywa.\nMilinganyo ya watu wazima ya Watson ya 1980 hutumia kategoria za wanaume/wanawake kutoka kwa data ya chanzo na huenda zisitoshee kila mtu au idadi ya watu.\nSio kwa watoto, ujauzito, dialysis, uvimbe, utambuzi au maamuzi ya kimatibabu.\nKwa maswali ya afya, muulize daktari aliyehitimu.","resultLiters":"Kadirio la jumla ya maji ya mwili","resultPercent":"Takriban sehemu ya uzani wa mwili","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"Kokotoa makadirio","example":"Jaribu mfano","reset":"Wazi","result":"Kadirio"},"messages":{"calculated":"Kadirio limekokotolewa.","checkInputs":"Angalia umri wa watu wazima, urefu, uzito na vitengo vilivyochaguliwa."},"additionalFaqs":[{"question":"Je, hiki ni kipimo cha maji au upungufu wa maji mwilini?","answer":"No. Inakadiria jumla ya maji ya mwili kutoka kwa mlinganyo wa idadi ya watu.\nHaiwezi kupima hali ya unyevu au kutambua upungufu wa maji mwilini."},{"question":"Je, asilimia inamaanisha nini?","answer":"Inakadiriwa lita kugawanywa na wingi wa mwili ulioingia, kutibu lita 1 ya maji kama kilo 1.\nSio lengo au alama ya masafa yenye afya."},{"question":"Nani hapaswi kutumia makadirio haya kwa maamuzi?","answer":"Haikusudiwa kwa watoto, ujauzito, dialysis, edema au maamuzi ya kimatibabu.\nDaktari anaweza kutathmini muktadha wa afya ya mtu binafsi na vipimo vya moja kwa moja."}],"copyLanguage":"sw","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"mr":{"name":"बॉडी वॉटर कॅल्क्युलेटर","title":"बॉडी वॉटर कॅल्क्युलेटर | UsefulVerse","description":"प्रकाशित वॉटसन समीकरणांसह प्रौढांच्या शरीरातील एकूण पाण्याचा अंदाज लावा.\nविनामूल्य, स्थानिक आणि वापर मर्यादा नाही;\nहायड्रेशन चाचणी नाही.","intro":"प्रकाशित मानववंशीय समीकरण वापरून प्रौढ वय, उंची आणि वजन यावरून शरीरातील एकूण पाण्याचा अंदाज लावा.\nअंदाजे लिटरमध्ये आणि प्रविष्ट केलेल्या शरीराच्या वस्तुमानाचा हिस्सा म्हणून पहा.","howQuestion":"शरीरातील एकूण पाण्याचा अंदाज कसा लावला जातो?","howAnswer":"वॉटसन समीकरण प्रकारांपैकी एक निवडा, प्रौढ वय, उंची आणि वजन प्रविष्ट करा, नंतर गणना करा.\nपरिणाम लोकसंख्येवर आधारित अंदाज आहे, थेट मोजमाप नाही.","privacyQuestion":"माझी मापे अपलोड केली आहेत का?","privacyAnswer":"क्र. गणना या ब्राउझरमध्ये स्थानिक पातळीवर चालते आणि मूल्ये या साधनाद्वारे अपलोड किंवा जतन केलेली नाहीत.","fields":{"equation":"वॉटसन समीकरण प्रकार","watsonMale":"पुरुष समीकरण","watsonFemale":"स्त्री समीकरण","age":"वय (वर्षे; प्रौढ 18-100)","height":"उंची","heightUnit":"उंची युनिट","weight":"वजन","weightUnit":"वजन युनिट","centimeters":"सेंटीमीटर (सेमी)","inches":"इंच (मध्ये)","kilograms":"किलोग्राम (किलो)","pounds":"पाउंड (lb)","accuracyNote":"फक्त अंदाज;\nते हायड्रेशन मोजत नाही किंवा किती प्यावे हे सांगत नाही.\nवॉटसनची 1980 प्रौढ समीकरणे त्यांच्या स्त्रोत डेटावरून पुरुष/स्त्री वर्गवारी वापरतात आणि प्रत्येक व्यक्ती किंवा लोकसंख्येला बसत नाहीत.\nअल्पवयीन, गर्भधारणा, डायलिसिस, एडेमा, निदान किंवा क्लिनिकल निर्णयांसाठी नाही.\nआरोग्यविषयक प्रश्नांसाठी, पात्र डॉक्टरांना विचारा.","resultLiters":"अंदाजे एकूण शरीरातील पाणी","resultPercent":"शरीराच्या वस्तुमानाचा अंदाजे हिस्सा","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"अंदाज मोजा","example":"उदाहरण वापरून पहा","reset":"साफ करा","result":"अंदाज"},"messages":{"calculated":"अंदाज काढला.","checkInputs":"प्रौढ वय, उंची, वजन आणि निवडलेले युनिट तपासा."},"additionalFaqs":[{"question":"ही हायड्रेशन किंवा डिहायड्रेशन चाचणी आहे का?","answer":"क्र. हे लोकसंख्येच्या समीकरणावरून शरीरातील एकूण पाण्याचा अंदाज लावते.\nते हायड्रेशन स्थिती मोजू शकत नाही किंवा निर्जलीकरणाचे निदान करू शकत नाही."},{"question":"टक्केवारी म्हणजे काय?","answer":"1 लिटर पाण्याला सुमारे 1 किलोग्रॅम मानून, एंटर केलेल्या शरीराच्या वस्तुमानाने भागले जाणारे अंदाजे लिटर आहे.\nहे लक्ष्य किंवा निरोगी-श्रेणी स्कोअर नाही."},{"question":"हा अंदाज निर्णयासाठी कोणी वापरू नये?","answer":"हे मुलांसाठी, गर्भधारणा, डायलिसिस, सूज किंवा क्लिनिकल निर्णयांसाठी नाही.\nएक चिकित्सक वैयक्तिक आरोग्य संदर्भ आणि थेट मोजमापांचे मूल्यांकन करू शकतो."}],"copyLanguage":"mr","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"te":{"name":"బాడీ వాటర్ కాలిక్యులేటర్","title":"బాడీ వాటర్ కాలిక్యులేటర్ | UsefulVerse","description":"ప్రచురించబడిన వాట్సన్ సమీకరణాలతో పెద్దల మొత్తం శరీర నీటిని అంచనా వేయండి.\nఉచిత, స్థానిక మరియు వినియోగ పరిమితి లేదు;\nఆర్ద్రీకరణ పరీక్ష కాదు.","intro":"ప్రచురించబడిన ఆంత్రోపోమెట్రిక్ సమీకరణాన్ని ఉపయోగించి పెద్దల వయస్సు, ఎత్తు మరియు బరువు నుండి మొత్తం శరీర నీటిని అంచనా వేయండి.\nఅంచనాను లీటర్లలో మరియు నమోదు చేసిన శరీర ద్రవ్యరాశిలో వాటాగా చూడండి.","howQuestion":"శరీరంలోని మొత్తం నీరు ఎలా అంచనా వేయబడుతుంది?","howAnswer":"వాట్సన్ ఈక్వేషన్ వేరియంట్‌లలో ఒకదాన్ని ఎంచుకోండి, పెద్దల వయస్సు, ఎత్తు మరియు బరువును నమోదు చేసి, ఆపై లెక్కించండి.\nఫలితం జనాభా ఆధారిత అంచనా, ప్రత్యక్ష కొలత కాదు.","privacyQuestion":"నా కొలతలు అప్‌లోడ్ చేయబడ్డాయా?","privacyAnswer":"సంఖ్య. ఈ బ్రౌజర్‌లో గణన స్థానికంగా నడుస్తుంది మరియు ఈ సాధనం ద్వారా విలువలు అప్‌లోడ్ చేయబడవు లేదా సేవ్ చేయబడవు.","fields":{"equation":"వాట్సన్ ఈక్వేషన్ వేరియంట్","watsonMale":"పురుష సమీకరణం","watsonFemale":"స్త్రీ సమీకరణం","age":"వయస్సు (సంవత్సరాలు; పెద్దలు 18–100)","height":"ఎత్తు","heightUnit":"ఎత్తు యూనిట్","weight":"బరువు","weightUnit":"బరువు యూనిట్","centimeters":"సెంటీమీటర్లు (సెం.మీ.)","inches":"అంగుళాలు (లో)","kilograms":"కిలోలు (కిలోలు)","pounds":"పౌండ్లు (lb)","accuracyNote":"అంచనా మాత్రమే;\nఇది ఆర్ద్రీకరణను కొలవదు ​​లేదా ఎంత త్రాగాలి అని చెప్పదు.\nవాట్సన్ యొక్క 1980 వయోజన సమీకరణాలు వారి మూల డేటా నుండి పురుష/ఆడ వర్గాలను ఉపయోగిస్తాయి మరియు ప్రతి వ్యక్తి లేదా జనాభాకు సరిపోకపోవచ్చు.\nమైనర్‌లు, గర్భం, డయాలసిస్, ఎడెమా, రోగ నిర్ధారణ లేదా క్లినికల్ నిర్ణయాల కోసం కాదు.\nఆరోగ్య ప్రశ్నల కోసం, అర్హత కలిగిన వైద్యుడిని అడగండి.","resultLiters":"అంచనా వేసిన మొత్తం శరీర నీరు","resultPercent":"శరీర ద్రవ్యరాశి యొక్క సుమారు వాటా","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"అంచనాను లెక్కించండి","example":"ఒక ఉదాహరణ ప్రయత్నించండి","reset":"క్లియర్","result":"అంచనా"},"messages":{"calculated":"అంచనా లెక్కించబడింది.","checkInputs":"పెద్దల వయస్సు, ఎత్తు, బరువు మరియు ఎంచుకున్న యూనిట్‌లను తనిఖీ చేయండి."},"additionalFaqs":[{"question":"ఇది హైడ్రేషన్ లేదా డీహైడ్రేషన్ పరీక్షా?","answer":"సంఖ్య. ఇది జనాభా సమీకరణం నుండి మొత్తం శరీర నీటిని అంచనా వేస్తుంది.\nఇది హైడ్రేషన్ స్థితిని కొలవదు ​​లేదా నిర్జలీకరణాన్ని నిర్ధారించదు."},{"question":"శాతం అంటే ఏమిటి?","answer":"ఇది 1 లీటరు నీటిని సుమారు 1 కిలోగ్రాముగా పరిగణిస్తూ, ప్రవేశించిన శరీర ద్రవ్యరాశితో విభజించబడిన లీటర్లను అంచనా వేయబడింది.\nఇది లక్ష్యం లేదా ఆరోగ్యకరమైన శ్రేణి స్కోర్ కాదు."},{"question":"నిర్ణయాల కోసం ఈ అంచనాను ఎవరు ఉపయోగించకూడదు?","answer":"ఇది పిల్లలు, గర్భం, డయాలసిస్, ఎడెమా లేదా క్లినికల్ నిర్ణయాల కోసం ఉద్దేశించబడలేదు.\nఒక వైద్యుడు వ్యక్తిగత ఆరోగ్య సందర్భం మరియు ప్రత్యక్ష కొలతలను అంచనా వేయవచ్చు."}],"copyLanguage":"te","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"ha":{"name":"Calculator Ruwan Jiki","title":"Calculator Ruwan Jiki | UsefulVerse","description":"Kiyasta yawan ruwan jiki na manya tare da ma'aunin Watson da aka buga.\nKyauta, na gida kuma babu iyakar amfani;\nba gwajin hydration ba.","intro":"Kiyasta jimillar ruwan jiki daga tsufa, tsayi da nauyi ta amfani da ma'aunin anthropometric da aka buga.\nDubi ƙiyasin a cikin lita kuma a matsayin rabon da aka shigar.","howQuestion":"Yaya aka kiyasta yawan ruwan jiki?","howAnswer":"Zaɓi ɗaya daga cikin bambance-bambancen lissafin Watson, shigar da shekarun girma, tsayi da nauyi, sannan lissafta.\nSakamakon shine kididdigar yawan jama'a, ba ma'auni kai tsaye ba.","privacyQuestion":"An loda ma'auni na?","privacyAnswer":"A'a. Lissafin yana gudana a cikin gida a cikin wannan mai binciken kuma ba a ɗora darajar ko adana ta wannan kayan aikin ba.","fields":{"equation":"bambancin equation Watson","watsonMale":"Ma'aunin maza","watsonFemale":"Ma'aunin mata","age":"Shekaru (shekaru; manya 18-100)","height":"Tsayi","heightUnit":"Tsawo naúrar","weight":"Nauyi","weightUnit":"Nau'in nauyi","centimeters":"santimita (cm)","inches":"Inci (a)","kilograms":"Kilogram (kg)","pounds":"fam (lb)","accuracyNote":"Ƙidaya kawai;\nbaya auna hydration ko ya gaya muku adadin abin da za ku sha.\nMatsakaicin manya na Watson na 1980 suna amfani da nau'ikan maza/mace daga bayanan tushen su kuma maiyuwa bazai dace da kowane mutum ko yawan jama'a ba.\nBa don ƙananan yara ba, ciki, dialysis, edema, ganewar asali ko yanke shawara na asibiti.\nDon tambayoyin lafiya, tambayi ƙwararren likita.","resultLiters":"Kiyasta yawan ruwan jiki","resultPercent":"Kimanin rabon jiki","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"Yi lissafin ƙididdiga","example":"Gwada misali","reset":"Share","result":"Kiyasin"},"messages":{"calculated":"Ƙididdiga.","checkInputs":"Bincika shekarun manya, tsayi, nauyi da zaɓaɓɓun raka'a."},"additionalFaqs":[{"question":"Shin wannan gwajin rashin ruwa ne ko rashin ruwa?","answer":"A'a. Ya kiyasta jimillar ruwan jiki daga ma'aunin yawan jama'a.\nBa zai iya auna yanayin ruwa ko tantance rashin ruwa ba."},{"question":"Menene ma'anar kashi?","answer":"An kiyasta lita ta hanyar adadin jiki wanda aka shiga, ana ɗaukar lita 1 na ruwa kamar kilo 1.\nBa manufa ba ce ko maki mai lafiya."},{"question":"Wanene bai kamata yayi amfani da wannan kimanta don yanke shawara ba?","answer":"Ba a yi nufin yara ba, ciki, dialysis, edema ko yanke shawara na asibiti.\nLikita na iya tantance mahallin lafiyar mutum da ma'auni kai tsaye."}],"copyLanguage":"ha","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"tl":{"name":"Body Water Calculator","title":"Body Water Calculator | UsefulVerse","description":"Tantyahin ang kabuuang tubig ng katawan ng nasa hustong gulang gamit ang na-publish na mga equation ng Watson.\nLibre, lokal at walang limitasyon sa…","intro":"Tantyahin ang kabuuang tubig sa katawan mula sa pang-adultong edad, taas at timbang gamit ang isang nai-publish na anthropometric equation.\nTingnan ang pagtatantya sa litro at bilang bahagi ng naipasok na masa ng katawan.","howQuestion":"Paano tinatantya ang kabuuang tubig sa katawan?","howAnswer":"Pumili ng isa sa mga variant ng Watson equation, ilagay ang edad, taas at timbang ng nasa hustong gulang, pagkatapos ay kalkulahin.\nAng resulta ay isang pagtatantya na nakabatay sa populasyon, hindi isang direktang pagsukat.","privacyQuestion":"Na-upload ba ang aking mga sukat?","privacyAnswer":"Hindi. Ang pagkalkula ay tumatakbo nang lokal sa browser na ito at ang mga halaga ay hindi na-upload o nai-save ng tool na ito.","fields":{"equation":"Watson equation variant","watsonMale":"Equation ng lalaki","watsonFemale":"Equation ng babae","age":"Edad (taon; nasa hustong gulang 18–100)","height":"Taas","heightUnit":"Taas na yunit","weight":"Timbang","weightUnit":"Timbang yunit","centimeters":"Sentimetro (cm)","inches":"Pulgada (sa)","kilograms":"Kilograms (kg)","pounds":"Pounds (lb)","accuracyNote":"Tantyahin lamang;\nhindi nito sinusukat ang hydration o sinasabi sa iyo kung gaano karaming inumin.\nGumagamit ang mga equation ng pang-adulto ng Watson noong 1980 ng mga kategorya ng lalaki/babae mula sa kanilang pinagmulang data at maaaring hindi magkasya sa bawat tao o populasyon.\nHindi para sa mga menor de edad, pagbubuntis, dialysis, edema, diagnosis o mga klinikal na desisyon.\nPara sa mga katanungan sa kalusugan, magtanong sa isang kwalipikadong clinician.","resultLiters":"Tinatayang kabuuang tubig sa katawan","resultPercent":"Tinatayang bahagi ng bigat ng katawan","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"Kalkulahin ang pagtatantya","example":"Subukan ang isang halimbawa","reset":"Maaliwalas","result":"Tantyahin"},"messages":{"calculated":"Nakalkula ang pagtatantya.","checkInputs":"Suriin ang pang-adultong edad, taas, timbang at mga napiling unit."},"additionalFaqs":[{"question":"Isa ba itong hydration o dehydration test?","answer":"Hindi. Tinatantya nito ang kabuuang tubig ng katawan mula sa isang equation ng populasyon.\nHindi nito masusukat ang katayuan ng hydration o masuri ang dehydration."},{"question":"Ano ang ibig sabihin ng porsyento?","answer":"Ito ay tinatayang litro na hinati sa pinasok na masa ng katawan, tinatrato ang 1 litro ng tubig bilang mga 1 kilo.\nIto ay hindi isang target o isang malusog na saklaw na marka."},{"question":"Sino ang hindi dapat gumamit ng pagtatantya na ito para sa mga desisyon?","answer":"Hindi ito inilaan para sa mga bata, pagbubuntis, dialysis, edema o mga klinikal na desisyon.\nMaaaring tasahin ng isang clinician ang indibidwal na konteksto ng kalusugan at mga direktang sukat."}],"copyLanguage":"tl","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"ta":{"name":"உடல் நீர் கால்குலேட்டர்","title":"உடல் நீர் கால்குலேட்டர் | UsefulVerse","description":"வெளியிடப்பட்ட வாட்சன் சமன்பாடுகளுடன் வயது வந்தவரின் மொத்த உடல் நீரை மதிப்பிடவும்.\nஇலவசம், உள்ளூர் மற்றும் பயன்பாட்டு வரம்பு இல்லை;\nநீரேற்றம் சோதனை அல்ல.","intro":"வெளியிடப்பட்ட ஆந்த்ரோபோமெட்ரிக் சமன்பாட்டைப் பயன்படுத்தி வயது, உயரம் மற்றும் எடை ஆகியவற்றிலிருந்து மொத்த உடல் நீரை மதிப்பிடவும்.\nமதிப்பீட்டை லிட்டரில் பார்க்கவும் மற்றும் உள்ளிடப்பட்ட உடல் எடையின் ஒரு பங்காகவும் பார்க்கவும்.","howQuestion":"மொத்த உடல் நீர் எவ்வாறு மதிப்பிடப்படுகிறது?","howAnswer":"வாட்சன் சமன்பாடு மாறுபாடுகளில் ஒன்றைத் தேர்ந்தெடுத்து, வயது வந்தோர் வயது, உயரம் மற்றும் எடையை உள்ளிட்டு, பின்னர் கணக்கிடவும்.\nஇதன் விளைவாக மக்கள் தொகை அடிப்படையிலான மதிப்பீடு, நேரடி அளவீடு அல்ல.","privacyQuestion":"எனது அளவீடுகள் பதிவேற்றப்பட்டதா?","privacyAnswer":"எண். கணக்கீடு இந்த உலாவியில் உள்நாட்டில் இயங்குகிறது, மேலும் இந்தக் கருவியால் மதிப்புகள் பதிவேற்றப்படவோ சேமிக்கப்படவோ இல்லை.","fields":{"equation":"வாட்சன் சமன்பாடு மாறுபாடு","watsonMale":"ஆண் சமன்பாடு","watsonFemale":"பெண் சமன்பாடு","age":"வயது (வயது; பெரியவர்கள் 18–100)","height":"உயரம்","heightUnit":"உயரம் அலகு","weight":"எடை","weightUnit":"எடை அலகு","centimeters":"சென்டிமீட்டர்கள் (செ.மீ.)","inches":"அங்குலங்கள் (உள்)","kilograms":"கிலோகிராம்கள் (கிலோ)","pounds":"பவுண்டுகள் (எல்பி)","accuracyNote":"மதிப்பீடு மட்டும்;\nஇது நீரேற்றத்தை அளவிடுவதில்லை அல்லது எவ்வளவு குடிக்க வேண்டும் என்று சொல்லவில்லை.\nவாட்சனின் 1980 வயது வந்தோருக்கான சமன்பாடுகள் ஆண்/பெண் வகைகளை அவற்றின் மூலத் தரவுகளிலிருந்து பயன்படுத்துகின்றன, மேலும் ஒவ்வொரு நபருக்கும் மக்கள்தொகைக்கும் பொருந்தாது.\nசிறார்களுக்கு அல்ல, கர்ப்பம், டயாலிசிஸ், எடிமா, நோய் கண்டறிதல் அல்லது மருத்துவ முடிவுகள்.\nஉடல்நலக் கேள்விகளுக்கு, தகுதி வாய்ந்த மருத்துவரிடம் கேளுங்கள்.","resultLiters":"மதிப்பிடப்பட்ட மொத்த உடல் நீர்","resultPercent":"உடல் நிறை தோராயமான பங்கு","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"மதிப்பீட்டைக் கணக்கிடவும்","example":"உதாரணத்தை முயற்சிக்கவும்","reset":"தெளிவு","result":"மதிப்பீடு"},"messages":{"calculated":"மதிப்பீடு கணக்கிடப்பட்டது.","checkInputs":"வயது வந்தோர் வயது, உயரம், எடை மற்றும் தேர்ந்தெடுக்கப்பட்ட அலகுகளைச் சரிபார்க்கவும்."},"additionalFaqs":[{"question":"இது நீரேற்றம் அல்லது நீரிழப்பு சோதனையா?","answer":"எண். இது மொத்த உடல் நீரை மக்கள் தொகை சமன்பாட்டிலிருந்து மதிப்பிடுகிறது.\nஇது நீரேற்றம் நிலையை அளவிடவோ அல்லது நீரிழப்பு கண்டறியவோ முடியாது."},{"question":"சதவீதம் என்றால் என்ன?","answer":"இது 1 லிட்டர் தண்ணீரை சுமார் 1 கிலோகிராம் எனக் கருதி, உள்ளிடப்பட்ட உடல் நிறைவால் வகுக்கப்படும் லிட்டர் என மதிப்பிடப்பட்டுள்ளது.\nஇது இலக்கு அல்லது ஆரோக்கியமான வரம்பு மதிப்பெண் அல்ல."},{"question":"இந்த மதிப்பீட்டை முடிவுகளுக்கு யார் பயன்படுத்தக்கூடாது?","answer":"இது குழந்தைகள், கர்ப்பம், டயாலிசிஸ், எடிமா அல்லது மருத்துவ முடிவுகளுக்காக அல்ல.\nஒரு மருத்துவர் தனிப்பட்ட சுகாதார சூழல் மற்றும் நேரடி அளவீடுகளை மதிப்பிட முடியும்."}],"copyLanguage":"ta","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"fa":{"name":"ماشین حساب آب بدن","title":"ماشین حساب آب بدن | UsefulVerse","description":"کل آب بدن بزرگسالان را با معادلات منتشر شده واتسون تخمین بزنید.\nرایگان، محلی و بدون محدودیت استفاده؛\nتست هیدراتاسیون نیست","intro":"کل آب بدن را از سن، قد و وزن بزرگسالان با استفاده از یک معادله آنتروپومتری منتشر شده تخمین بزنید.\nبرآورد را بر حسب لیتر و به عنوان سهم توده بدن وارد شده ببینید.","howQuestion":"آب کل بدن چگونه تخمین زده می شود؟","howAnswer":"یکی از انواع معادله واتسون را انتخاب کنید، سن، قد و وزن بزرگسالان را وارد کنید، سپس محاسبه کنید.\nنتیجه یک تخمین مبتنی بر جمعیت است، نه یک اندازه گیری مستقیم.","privacyQuestion":"آیا اندازه گیری های من آپلود شده است؟","privacyAnswer":"نه. محاسبه به صورت محلی در این مرورگر اجرا می شود و مقادیر توسط این ابزار آپلود یا ذخیره نمی شوند.","fields":{"equation":"نوع معادله واتسون","watsonMale":"معادله مرد","watsonFemale":"معادله زن","age":"سن (سال، بزرگسالان 18 تا 100)","height":"ارتفاع","heightUnit":"واحد ارتفاع","weight":"وزن","weightUnit":"واحد وزن","centimeters":"سانتی متر (سانتی متر)","inches":"اینچ (اینچ)","kilograms":"کیلوگرم (کیلوگرم)","pounds":"پوند (پوند)","accuracyNote":"فقط برآورد;\nهیدراتاسیون را اندازه گیری نمی کند یا به شما نمی گوید که چقدر بنوشید.\nمعادلات بزرگسالان واتسون در سال 1980 از مقوله‌های مرد/زن از داده‌های منبع خود استفاده می‌کند و ممکن است برای هر فرد یا جمعیتی مناسب نباشد.\nنه برای افراد زیر سن قانونی، بارداری، دیالیز، ادم، تشخیص یا تصمیمات بالینی.\nبرای سؤالات بهداشتی، از یک پزشک متخصص بپرسید.","resultLiters":"کل آب بدن برآورد شده است","resultPercent":"سهم تقریبی توده بدن","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"محاسبه برآورد","example":"یک مثال را امتحان کنید","reset":"پاک","result":"برآورد"},"messages":{"calculated":"برآورد محاسبه شده.","checkInputs":"سن بزرگسالان، قد، وزن و واحدهای انتخابی را بررسی کنید."},"additionalFaqs":[{"question":"آیا این تست هیدراتاسیون است یا کم آبی؟","answer":"شماره کل آب بدن را از معادله جمعیت تخمین می زند.\nنمی تواند وضعیت هیدراتاسیون را اندازه گیری کند یا کم آبی را تشخیص دهد."},{"question":"درصد یعنی چی؟","answer":"تخمین زده می شود لیتر تقسیم بر توده بدن وارد شده، 1 لیتر آب حدود 1 کیلوگرم است.\nاین یک امتیاز هدف یا یک امتیاز با برد سالم نیست."},{"question":"چه کسی نباید از این تخمین برای تصمیم گیری استفاده کند؟","answer":"برای کودکان، بارداری، دیالیز، ادم یا تصمیمات بالینی در نظر گرفته نشده است.\nیک پزشک می تواند زمینه سلامت فردی و اندازه گیری های مستقیم را ارزیابی کند."}],"copyLanguage":"fa","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"am":{"name":"የሰውነት ውሃ ማስያ","title":"የሰውነት ውሃ ማስያ | UsefulVerse","description":"የታተመው የዋትሰን እኩልታዎች የአዋቂዎች አጠቃላይ የሰውነት ውሃ ይገምቱ።\nነፃ፣ አካባቢያዊ እና የአጠቃቀም ገደብ የለም;\nየውሃ ማጣራት አይደለም.","intro":"የታተመ አንትሮፖሜትሪክ እኩልታ በመጠቀም አጠቃላይ የሰውነት ውሃ ከአዋቂዎች ዕድሜ፣ ቁመት እና ክብደት ይገምቱ።\nግምቱን በሊትር ይመልከቱ እና የገባው የሰውነት ክብደት ድርሻ።","howQuestion":"አጠቃላይ የሰውነት ውሃ እንዴት ይገመታል?","howAnswer":"ከWatson እኩልታ ልዩነቶች ውስጥ አንዱን ይምረጡ፣የአዋቂዎችን እድሜ፣ቁመት እና ክብደት ያስገቡ እና ከዚያ ያሰሉ።\nውጤቱ ህዝብን መሰረት ያደረገ ግምት እንጂ ቀጥተኛ መለኪያ አይደለም።","privacyQuestion":"መለኪያዎቼ ተሰቅለዋል?","privacyAnswer":"አይ.ስሌቱ በዚህ አሳሽ ውስጥ በአካባቢው ይሰራል እና እሴቶቹ በዚህ መሳሪያ አልተሰቀሉም ወይም አይቀመጡም.","fields":{"equation":"የዋትሰን እኩልታ ልዩነት","watsonMale":"ወንድ እኩልታ","watsonFemale":"የሴቶች እኩልታ","age":"ዕድሜ (ዓመታት፤ አዋቂዎች 18–100)","height":"ቁመት","heightUnit":"ቁመት አሃድ","weight":"ክብደት","weightUnit":"የክብደት አሃድ","centimeters":"ሴንቲሜትር (ሴሜ)","inches":"ኢንች (ውስጥ)","kilograms":"ኪሎ ግራም (ኪግ)","pounds":"ፓውንድ (ፓውንድ)","accuracyNote":"ግምት ብቻ;\nእርጥበት አይለካም ወይም ምን ያህል መጠጣት እንዳለብዎት አይነግርዎትም.\nየዋትሰን 1980 የአዋቂዎች እኩልታዎች ወንድ/ሴት ምድቦችን ከምንጭ መረጃቸው ይጠቀማሉ እና ለእያንዳንዱ ሰው ወይም ህዝብ ላይስማማ ይችላል።\nለአካለ መጠን ያልደረሱ ልጆች፣ እርግዝና፣ ዳያሊስስ፣ እብጠት፣ ምርመራ ወይም ክሊኒካዊ ውሳኔዎች አይደሉም።\nለጤና ጥያቄዎች፣ ብቃት ያለው የህክምና ባለሙያ ይጠይቁ።","resultLiters":"የተገመተው አጠቃላይ የሰውነት ውሃ","resultPercent":"የሰውነት ብዛት ግምታዊ ድርሻ","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"ግምት አስላ","example":"አንድ ምሳሌ ይሞክሩ","reset":"ግልጽ","result":"ግምት"},"messages":{"calculated":"ግምት ይሰላል።","checkInputs":"የአዋቂውን ዕድሜ፣ ቁመት፣ ክብደት እና የተመረጡ ክፍሎችን ያረጋግጡ።"},"additionalFaqs":[{"question":"ይህ የእርጥበት ወይም የእርጥበት ምርመራ ነው?","answer":"ቁጥር አጠቃላይ የሰውነት ውሃ ከሕዝብ እኩልነት ይገመታል።\nየእርጥበት ሁኔታን መለካት ወይም ድርቀትን መመርመር አይችልም."},{"question":"መቶኛ ምን ማለት ነው?","answer":"በገባው የሰውነት ክብደት የተከፋፈለ ሊትር ይገመታል፣ 1 ሊትር ውሃ ወደ 1 ኪሎግራም በማከም።\nዒላማ ወይም ጤናማ-ክልል ነጥብ አይደለም."},{"question":"ይህንን ግምት ለውሳኔ መጠቀም የማይገባው ማነው?","answer":"ለህጻናት፣ለእርግዝና፣ለዳያሊስስ፣ለእብጠት ወይም ለክሊኒካዊ ውሳኔዎች የታሰበ አይደለም።\nአንድ የሕክምና ባለሙያ የግለሰብን የጤና ሁኔታ እና ቀጥተኛ መለኪያዎችን ሊገመግም ይችላል."}],"copyLanguage":"am","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"gu":{"name":"બોડી વોટર કેલ્ક્યુલેટર","title":"બોડી વોટર કેલ્ક્યુલેટર | UsefulVerse","description":"પ્રકાશિત વોટસન સમીકરણો સાથે પુખ્ત વયના કુલ શરીરના પાણીનો અંદાજ કાઢો.\nમફત, સ્થાનિક અને કોઈ વપરાશ મર્યાદા નથી;\nહાઇડ્રેશન ટેસ્ટ નથી.","intro":"એક પ્રકાશિત એન્થ્રોપોમેટ્રિક સમીકરણનો ઉપયોગ કરીને પુખ્ત વય, ઊંચાઈ અને વજન પરથી શરીરના કુલ પાણીનો અંદાજ કાઢો.\nઅંદાજને લિટરમાં અને દાખલ કરેલ બોડી માસના હિસ્સા તરીકે જુઓ.","howQuestion":"શરીરના કુલ પાણીનો અંદાજ કેવી રીતે થાય છે?","howAnswer":"વોટસન સમીકરણ પ્રકારોમાંથી એક પસંદ કરો, પુખ્ત વય, ઊંચાઈ અને વજન દાખલ કરો, પછી ગણતરી કરો.\nપરિણામ એ વસ્તી આધારિત અંદાજ છે, સીધું માપન નથી.","privacyQuestion":"શું મારું માપ અપલોડ કરવામાં આવ્યું છે?","privacyAnswer":"નંબર. ગણતરી આ બ્રાઉઝરમાં સ્થાનિક રીતે ચાલે છે અને આ ટૂલ દ્વારા મૂલ્યો અપલોડ અથવા સાચવવામાં આવતા નથી.","fields":{"equation":"વોટસન સમીકરણ વેરિઅન્ટ","watsonMale":"પુરુષ સમીકરણ","watsonFemale":"સ્ત્રી સમીકરણ","age":"ઉંમર (વર્ષ; વયસ્કો 18–100)","height":"ઊંચાઈ","heightUnit":"ઊંચાઈ એકમ","weight":"વજન","weightUnit":"વજન એકમ","centimeters":"સેન્ટિમીટર (સેમી)","inches":"ઇંચ (માં)","kilograms":"કિલોગ્રામ (કિલો)","pounds":"પાઉન્ડ (lb)","accuracyNote":"માત્ર અંદાજ;\nતે હાઇડ્રેશનને માપતું નથી અથવા તમને કેટલું પીવું તે કહેતું નથી.\nવોટસનના 1980 પુખ્ત સમીકરણો તેમના સ્ત્રોત ડેટામાંથી પુરૂષ/સ્ત્રી શ્રેણીઓનો ઉપયોગ કરે છે અને તે દરેક વ્યક્તિ અથવા વસ્તીને બંધબેસતું નથી.\nસગીરો, ગર્ભાવસ્થા, ડાયાલિસિસ, એડીમા, નિદાન અથવા ક્લિનિકલ નિર્ણયો માટે નહીં.\nસ્વાસ્થ્યના પ્રશ્નો માટે, લાયકાત ધરાવતા ચિકિત્સકને પૂછો.","resultLiters":"અંદાજિત કુલ બોડી વોટર","resultPercent":"બોડી માસનો અંદાજિત હિસ્સો","equationNote":"Watson et al. (1980): male = 2.447 − 0.09516 × age + 0.1074 × height(cm) + 0.3362 × weight(kg); female = −2.097 + 0.1069 × height(cm) + 0.2466 × weight(kg). The percentage treats 1 L of water as approximately 1 kg."},"actions":{"calculate":"અંદાજની ગણતરી કરો","example":"ઉદાહરણ અજમાવી જુઓ","reset":"સાફ કરો","result":"અંદાજ"},"messages":{"calculated":"અંદાજિત ગણતરી.","checkInputs":"પુખ્ત વય, ઊંચાઈ, વજન અને પસંદ કરેલા એકમો તપાસો."},"additionalFaqs":[{"question":"શું આ હાઇડ્રેશન કે ડીહાઇડ્રેશન ટેસ્ટ છે?","answer":"નંબર. તે વસ્તીના સમીકરણમાંથી શરીરના કુલ પાણીનો અંદાજ કાઢે છે.\nતે હાઇડ્રેશનની સ્થિતિને માપી શકતું નથી અથવા ડિહાઇડ્રેશનનું નિદાન કરી શકતું નથી."},{"question":"ટકાનો અર્થ શું થાય છે?","answer":"1 લિટર પાણીને લગભગ 1 કિલોગ્રામ તરીકે ગણીને દાખલ કરેલ બોડી માસ દ્વારા વિભાજિત કરાયેલ અંદાજિત લિટર છે.\nતે લક્ષ્ય અથવા તંદુરસ્ત શ્રેણીનો સ્કોર નથી."},{"question":"કોણે નિર્ણયો માટે આ અંદાજનો ઉપયોગ ન કરવો જોઈએ?","answer":"તે બાળકો, ગર્ભાવસ્થા, ડાયાલિસિસ, એડીમા અથવા ક્લિનિકલ નિર્ણયો માટે બનાવાયેલ નથી.\nએક ચિકિત્સક વ્યક્તિગત સ્વાસ્થ્ય સંદર્ભ અને સીધા માપનું મૂલ્યાંકન કરી શકે છે."}],"copyLanguage":"gu","localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"}});
